-- id=610 | Frapin
UPDATE producer
SET
  founded_year = 1270,
  name_en = 'Frapin',
  name_ko = '프라팡',
  search_keywords = 'Frapin, Cognac Frapin, Maison Frapin, Château Fontpinot, Chateau Fontpinot, 프라팡, 프라핀',
  website = 'https://www.cognac-frapin.com/',
  description_en = 'Frapin is a family Cognac house whose winegrowing and distilling heritage is traced by the house to 1270. Its identity is unusually estate-focused: the family cultivates about 240 hectares of vines in a single holding in Grande Champagne, Cognac’s Premier Cru, around Segonzac, and controls the process from vineyard work and harvest through distillation, ageing and bottling. The estate includes Château Fontpinot, and Frapin is known for distilling wines with their fine lees and for long maturation in a range of dry and humid cellars, allowing the cellar master to shape texture and aromatic development through both spirit selection and cellar environment. Rather than operating mainly as a blender buying broadly across the appellation, Frapin presents itself as a single-family, single-estate producer whose style is closely tied to its Grande Champagne soils, stocks of mature eaux-de-vie and centuries of accumulated vineyard knowledge.',
  description_ko = '프라팡(Frapin)은 하우스가 공식적으로 1270년까지 거슬러 올라간다고 설명하는 포도재배·증류 전통을 지닌 가족 경영 코냑 생산자입니다. 가장 큰 특징은 네고시앙 중심의 대형 하우스와 달리 그랑드 샹파뉴(Grande Champagne) 중심의 약 240헥타르 단일 소유 포도밭을 기반으로 포도 재배와 수확, 양조, 증류, 숙성, 병입까지 생산 전 과정을 직접 관리한다는 점입니다. 세곤작(Segonzac) 일대의 포도밭과 샤토 퐁피노(Château Fontpinot)를 중심으로 하며, 와인의 미세한 리(lees)를 함께 증류하는 전통과 건조·습윤도가 다른 숙성고를 활용해 원액의 질감과 향의 발달을 세밀하게 조정합니다. 프라팡의 정체성은 단순히 오래된 브랜드라는 데 있기보다, 한 가족이 같은 그랑드 샹파뉴 테루아에서 축적해 온 포도재배 경험과 자체 원액 재고, 장기 숙성 능력을 하나의 생산 체계로 이어 온 ‘에스테이트 중심 코냑 하우스’라는 데 있습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 610;

-- id=640 | Henri Mounier
UPDATE producer
SET
  founded_year = 1858,
  name_en = 'Henri Mounier',
  name_ko = '헨리 무니에',
  search_keywords = 'Henri Mounier, H. Mounier, H.Mounier, Mounier et Compagnie, Mounier & Co, Henri Mounier Cognac, 헨리 무니에, 앙리 무니에',
  website = 'https://www.hmounier.fr/',
  description_en = 'Henri Mounier is a historic Cognac company founded in 1858, when former merchant-navy captain Henri Mounier joined his father-in-law Jean Salmon, a cellar master, and partner Eugène Bellet to create Mounier et Compagnie. The firm developed from a regional wine-and-spirit trading business into a dedicated Cognac house and was an early participant in the shift toward bottled branded Cognac in the nineteenth century. Today the company operates from the Cognac area with production and ageing facilities around Gensac-la-Pallue and manages a portfolio that has included Henri Mounier and other established Cognac labels. Its history is therefore less that of a single vineyard estate than of a professional blending, maturation and brand-building house, drawing on cellar-master expertise and long commercial links to international markets. The modern company combines this historical négociant role with contemporary sourcing, ageing, quality-control and export capabilities.',
  description_ko = '헨리 무니에(Henri Mounier)는 1858년 상선 선장 출신의 앙리 무니에가 장인이자 셀러 마스터였던 장 살몽(Jean Salmon), 사업 파트너 외젠 벨레(Eugène Bellet)와 함께 ‘Mounier et Compagnie’를 설립하면서 시작된 역사적인 코냑 회사입니다. 초기에는 와인과 증류주 거래를 기반으로 성장했으며, 19세기 후반 코냑 산업이 벌크 거래에서 병입 브랜드 중심으로 전환되는 과정에도 일찍 참여했습니다. 오늘날에는 코냑 지역, 특히 Gensac-la-Pallue 일대의 숙성·생산 기반을 통해 여러 코냑 브랜드를 관리하는 전문 하우스로 이어지고 있습니다. 단일 포도원만을 강조하는 도멘형 생산자라기보다는 다양한 원액의 선별, 숙성, 블렌딩, 품질 관리와 국제 유통 역량을 축적해 온 네고시앙형 하우스에 가깝고, 오랜 셀러 마스터 전통과 수출 경험이 생산자 정체성의 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 640;

-- id=615 | Daniel Bouju
UPDATE producer
SET
  founded_year = 1805,
  name_en = 'Daniel Bouju',
  name_ko = '다니엘 부쥬',
  search_keywords = 'Daniel Bouju, Cognac Daniel Bouju, Bouju, Domaine Daniel Bouju, 다니엘 부쥬, 다니엘 부주',
  website = 'https://www.cognac-daniel-bouju.com/',
  description_en = 'Daniel Bouju is an independent family Cognac estate in Saint-Preuil whose winery history is traced to 1805 and has continued through seven generations. The family farms roughly 30 hectares in the heart of Grande Champagne, making the house strongly terroir-led rather than primarily a merchant blender. Vineyard work, distillation and ageing are handled within the family production chain, with an emphasis on reasoned viticulture, restrained use of treatments and preservation of the character of Grande Champagne fruit. Bouju is particularly associated with traditional Charentais double distillation and long ageing, including mature expressions that spend extended periods in oak. The producer’s appeal is its continuity: a relatively small estate, a clearly defined Premier Cru origin and a style shaped by family decisions at every stage from the vineyard to the cellar.',
  description_ko = '다니엘 부쥬(Daniel Bouju)는 생프뢰이(Saint-Preuil)에 자리한 독립 가족 경영 코냑 생산자로, 공식 역사상 1805년에 시작되어 현재까지 7세대에 걸쳐 이어지고 있습니다. 약 30헥타르의 포도밭이 그랑드 샹파뉴 중심부에 위치해 있어 여러 지역의 원액을 대규모로 조달하는 네고시앙형 하우스보다는 테루아와 자가 생산 비중이 높은 도멘형 생산자에 가깝습니다. 포도 재배부터 전통적인 샤랑테식 이중 증류, 숙성까지 가족이 밀접하게 관여하며, 합리적 농법과 농약 사용 절감 등 포도밭의 장기적인 건전성을 중시합니다. 특히 그랑드 샹파뉴 원액을 오랜 기간 오크통에서 숙성시키는 전통이 잘 알려져 있으며, 생산 규모보다 한 크뤼의 성격과 세대 간 기술 전승을 일관되게 보여 주는 하우스라는 점이 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 615;

-- id=597 | Camus
UPDATE producer
SET
  founded_year = 1863,
  name_en = 'Camus',
  name_ko = '까뮤',
  search_keywords = 'Camus, CAMUS Cognac, Camus La Grande Marque, Maison Camus, 까뮤, 카뮈, 카뮤',
  website = 'https://camus.fr/',
  description_en = 'CAMUS was founded in 1863 by Jean-Baptiste Camus and remains one of the best-known large independent family-owned Cognac houses. Five generations have developed the company while retaining family control, and the house has made Borderies a central part of its identity, including family vineyard holdings consolidated over time in Cognac’s smallest cru. CAMUS combines estate viticulture with broader Cognac-house skills in sourcing, distillation, ageing and blending; its modern production philosophy is especially associated with detailed control of distillation and the capture of highly aromatic fractions of the spirit. The house has also built a substantial international presence without becoming part of one of the major global drinks conglomerates. Its producer identity therefore joins two scales that are not always found together in Cognac: a substantial worldwide brand and a still family-directed house with a distinctive Borderies heritage and continuing technical focus on aromatic intensity.',
  description_ko = '까뮤(CAMUS)는 장바티스트 까뮤(Jean-Baptiste Camus)가 1863년에 설립한 코냑 하우스로, 현재까지 가족 지배를 유지하고 있는 대표적인 대형 독립 하우스 가운데 하나입니다. 5세대에 걸쳐 사업을 확장해 왔으며, 코냑의 가장 작은 크뤼인 보르드리(Borderies)를 하우스 정체성의 핵심으로 삼아 가족 소유 포도밭을 지속적으로 확보·관리해 왔습니다. 자가 포도재배뿐 아니라 원액 선별, 증류, 숙성, 블렌딩까지 대형 코냑 하우스가 요구하는 전체 역량을 갖추고 있으며, 현대에는 특히 향이 풍부한 증류 구간을 정교하게 선별하고 증류 조건을 세밀하게 제어하는 기술적 접근을 강조합니다. 글로벌 브랜드 규모를 갖추면서도 거대 주류 그룹에 편입되지 않은 가족 경영 구조, 보르드리 테루아에 대한 오랜 투자, 향의 강도를 중시하는 생산 철학이 까뮤를 설명하는 핵심 요소입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 597;

-- id=618 | Godet
UPDATE producer
SET
  founded_year = 1588,
  name_en = 'Godet',
  name_ko = '고데',
  search_keywords = 'Godet, Cognac Godet, Maison Godet, Godet Freres, Godet Frères, 고데, 고데 프레르, 메종 고데',
  website = 'https://cognacgodet.com/',
  description_en = 'Godet is a La Rochelle-based family Cognac house that presents its lineage as extending back to 1588, when the family’s early distilling activity received royal recognition. The company also distinguishes 1782 as an important point when Gédéon-Louis Godet formalized the house and its bottled commercial identity, so its history is best understood as a centuries-long family tradition that gradually became a recognizable Cognac business. Now represented by the fifteenth generation, Godet emphasizes an Atlantic or maritime identity shaped by La Rochelle, coastal cellars and the family’s long connection to seaborne trade. The modern house works with classic Cognac as well as unusual historical grape varieties and limited projects, while maintaining a strong focus on maturation, blending and family-held stocks. Its significance lies in combining one of the region’s longest family narratives with a location and style that are deliberately distinct from the Cognac town-centered image of many competitors.',
  description_ko = '고데(Godet)는 라로셸(La Rochelle)을 기반으로 하는 가족 경영 코냑 하우스로, 공식적으로는 가문의 증류 활동과 왕실의 인정을 근거로 1588년까지 역사를 거슬러 올라간다고 설명합니다. 동시에 1782년은 Gédéon-Louis Godet가 하우스의 상업적 형태와 병입 정체성을 본격적으로 정립한 중요한 시점으로 제시되므로, ‘가문 증류 전통의 기원’과 ‘근대적 코냑 하우스의 형성’을 구분해 이해하는 것이 정확합니다. 현재 15세대가 전통을 이어 가며, 코냑 시내보다 대서양 항구도시 라로셸과 해상 교역, 해양성 숙성 환경을 강조하는 독특한 정체성을 갖고 있습니다. 전통적인 코냑 외에도 역사적 포도 품종과 한정 프로젝트를 다루며, 장기간 축적된 가족 원액과 숙성·블렌딩 노하우를 기반으로 ‘해양적 코냑 하우스’라는 차별화된 위치를 유지하고 있습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 618;

-- id=619 | Larsen
UPDATE producer
SET
  founded_year = 1926,
  name_en = 'Larsen',
  name_ko = '라르센',
  search_keywords = 'Larsen, Larsen Cognac, Cognac Larsen, Viking Ship Cognac, 라르센, 라센 코냑',
  website = 'https://www.larsencognac.com/',
  description_en = 'Larsen Cognac was founded in 1926 by Jens Reidar Larsen, a Norwegian who left Tromsø, settled in southwest France and built a Cognac house with an unusually strong Nordic identity. The brand became famous internationally for its Viking imagery and ship-shaped presentation, but its production identity is centered on a fruit-driven, clean style rather than packaging alone. Larsen describes its approach as double distillation without lees, careful selection of the heart of the distillate and blending designed to preserve freshness, purity and balance. As a house, it is an example of Cognac’s long international commercial history: founded by an outsider who became part of the region, then developed for export markets while working within the appellation’s traditional distillation and maturation framework. Its Norwegian origin remains a core part of the house story almost a century after its creation.',
  description_ko = '라르센(Larsen)은 노르웨이 트롬쇠 출신의 옌스 레이다르 라르센(Jens Reidar Larsen)이 프랑스 남서부에 정착한 뒤 1926년에 설립한 코냑 하우스입니다. 바이킹과 배 모양의 병 디자인으로 국제적으로 널리 알려졌지만, 생산자 관점에서 더 중요한 특징은 과실의 선명함과 깨끗한 스타일을 지향하는 증류·블렌딩 철학입니다. 하우스는 리(lees)를 제외한 와인을 샤랑테식으로 이중 증류하고, 증류액의 핵심 구간을 정밀하게 선별해 신선함·순수함·균형을 유지하는 방식을 강조합니다. 프랑스인이 아닌 창립자가 코냑 지역에 뿌리내려 수출 중심의 하우스를 성장시켰다는 점에서 코냑의 국제 교역 역사를 잘 보여 주며, 설립 이후 거의 한 세기가 지난 현재도 노르웨이 출신 창립자의 ‘바이킹’ 정체성이 브랜드와 하우스의 핵심 서사로 남아 있습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 619;

-- id=620 | Bache-Gabrielsen
UPDATE producer
SET
  founded_year = 1905,
  name_en = 'Bache-Gabrielsen',
  name_ko = '바슈-가브리엘센',
  search_keywords = 'Bache-Gabrielsen, Bache Gabrielsen, Thomas Bache-Gabrielsen, Dupuy, 바슈 가브리엘센, 바슈-가브리엘센, 바체 가브리엘센',
  website = 'https://bache-gabrielsen.com/',
  description_en = 'Bache-Gabrielsen was established in 1905 when Norwegian Thomas Bache-Gabrielsen and his compatriot Peter Rustad acquired the older Cognac house A. Edmond Dupuy. The company remained closely linked to Scandinavian markets while becoming a fully rooted Cognac producer, and it is now carried by the fourth generation of the Bache-Gabrielsen family. Unlike a single-cru estate, the house works as a blender and merchant with access to eaux-de-vie from across the appellation, using long-term grower relationships, cellar ageing and assembly to maintain a recognizable house style. In recent years it has also presented organic and more eco-designed releases, showing an effort to combine a traditional independent-house structure with contemporary environmental expectations. The producer’s character is therefore defined by Norwegian entrepreneurial origins, family continuity in Cognac, independent blending expertise and a particularly strong historical presence in Northern Europe.',
  description_ko = '바슈-가브리엘센(Bache-Gabrielsen)은 노르웨이 출신 토마스 바슈-가브리엘센(Thomas Bache-Gabrielsen)과 피터 루스타드(Peter Rustad)가 1905년 기존 코냑 하우스 A. Edmond Dupuy를 인수하면서 출범했습니다. 창업 이후 스칸디나비아 시장과 강한 연결을 유지하는 동시에 코냑 지역에 완전히 뿌리내렸고, 현재는 바슈-가브리엘센 가문의 4세대가 하우스를 이어 갑니다. 특정 단일 크뤼의 자가 포도밭만으로 생산하는 도멘형이라기보다는 코냑 전역의 재배농가와 장기 관계를 구축하고 원액을 선별·숙성·블렌딩해 고유 스타일을 만드는 독립 네고시앙형 하우스입니다. 최근에는 유기농 원액과 친환경 설계를 강조한 제품도 선보이며 전통적인 가족 독립 경영과 현대적인 지속가능성 요구를 함께 반영하고 있습니다. 노르웨이 창업 배경, 4세대 가족 경영, 북유럽에서의 강한 역사적 입지, 독립 블렌딩 역량이 하우스의 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 620;

-- id=621 | Braastad (Tiffon)
UPDATE producer
SET
  founded_year = 1875,
  name_en = 'Braastad (Tiffon)',
  name_ko = '브라스타드 (티퐁)',
  search_keywords = 'Braastad, Braastad Cognac, Tiffon, Cognac Tiffon, Tiffon-Braastad, 브라스타드, 브라스타드 코냑, 티퐁, 티폰',
  website = 'https://braastad.com/',
  description_en = 'Braastad Cognac is the modern family brand closely tied to Maison Tiffon, which was founded in Jarnac in 1875 by Médéric Tiffon. The Braastad family entered the story through Sverre Braastad of Norway, and successive generations have continued the company as an independent family producer. The house owns vineyard holdings in Grande Champagne and Fins Bois and combines estate-grown fruit with the broader skills of distillation, maturation, selection and blending. This gives it a hybrid identity: more vertically integrated than a pure merchant house, yet able to create a broad range of Cognacs rather than expressing only one parcel or cru. The Tiffon and Braastad names therefore represent two chapters of the same producer history—French nineteenth-century house origins and a Norwegian-French family line that has carried the business forward through multiple generations.',
  description_ko = '브라스타드(Braastad)는 1875년 메데릭 티퐁(Médéric Tiffon)이 자르낙(Jarnac)에서 설립한 메종 티퐁(Maison Tiffon)의 역사와 직접 연결된 가족 코냑 브랜드입니다. 이후 노르웨이 출신 스베레 브라스타드(Sverre Braastad)가 가문에 합류하면서 오늘날의 브라스타드-티퐁 계보가 형성됐고, 여러 세대에 걸쳐 독립 가족 경영을 유지해 왔습니다. 하우스는 그랑드 샹파뉴와 팽 부아(Fins Bois)에 자체 포도밭을 보유하며, 자가 재배 원료에 더해 증류·숙성·선별·블렌딩까지 폭넓은 생산 역량을 갖춥니다. 따라서 순수 네고시앙보다 수직계열화가 강하지만 단일 밭의 표현에만 머무르지 않는 하우스형 생산자라는 점이 특징입니다. ‘Tiffon’은 19세기 프랑스에서 시작된 하우스의 뿌리를, ‘Braastad’는 이후 이어진 노르웨이-프랑스 가족 경영의 계보를 나타내는 두 이름으로 이해할 수 있습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 621;

-- id=622 | De Luze
UPDATE producer
SET
  founded_year = 1822,
  name_en = 'De Luze',
  name_ko = '드 뤼즈',
  search_keywords = 'De Luze, Cognac De Luze, Maison De Luze, Boinaud, Boinaud Family, 드 뤼즈, 드루즈, 들뤼즈',
  website = 'https://cognacdeluze.com/',
  description_en = 'De Luze was founded in 1822 by Alfred De Luze and developed as a Cognac house with a long reputation for elegant Fine Champagne blends. Since 2006 the brand has belonged to the Boinaud family, one of the region’s major winegrowing and distilling families, which gives the modern house an unusually integrated production base. The family controls a very large vineyard estate centered in Grande Champagne and can oversee viticulture, distillation, maturation and blending rather than depending entirely on spot-market purchases of eaux-de-vie. De Luze’s house identity is especially associated with Fine Champagne, the appellation category combining Grande Champagne and Petite Champagne with a required majority from Grande Champagne. The contemporary producer therefore joins a nineteenth-century brand heritage with the scale and technical resources of a large family vineyard-distillery operation.',
  description_ko = '드 뤼즈(De Luze)는 알프레드 드 뤼즈(Alfred De Luze)가 1822년에 설립한 코냑 하우스로, 오랫동안 우아한 스타일의 파인 샹파뉴(Fine Champagne) 코냑을 중요한 정체성으로 삼아 왔습니다. 2006년부터는 코냑 지역의 대형 포도재배·증류 가문인 부아노(Boinaud) 가족이 브랜드를 소유하고 있어, 현대의 드 뤼즈는 전통적인 브랜드 역사와 대규모 자가 생산 기반을 함께 갖춘 구조가 되었습니다. 부아노 가문은 그랑드 샹파뉴를 중심으로 매우 큰 포도밭을 관리하며 재배, 증류, 숙성, 블렌딩을 폭넓게 직접 통제할 수 있습니다. 드 뤼즈가 강조하는 파인 샹파뉴는 그랑드 샹파뉴와 프티트 샹파뉴 원액을 사용하고 그중 그랑드 샹파뉴가 과반을 차지해야 하는 법적 범주입니다. 즉 오늘날의 드 뤼즈는 19세기 하우스의 브랜드 유산과 현대적 가족 포도원·증류소의 규모를 결합한 생산자입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 622;

-- id=623 | Maxime Trijol
UPDATE producer
SET
  founded_year = 1859,
  name_en = 'Maxime Trijol',
  name_ko = '막심 트리욜',
  search_keywords = 'Maxime Trijol, Cognac Maxime Trijol, Trijol, 막심 트리욜, 막심 트리졸',
  website = 'https://www.maxime-trijol.com/',
  description_en = 'Maxime Trijol is a family Cognac producer whose distilling history began in 1859 with the installation of the family’s first still at Saint-Martial-sur-Né. Across six generations the business expanded from winegrowing and distillation into a vertically integrated house that cultivates vines, distils, ages and bottles its own Cognac while also developing professional distilling expertise. The family’s production history includes work as brokers and contract distillers before the Maxime Trijol name became a fully developed house, and today its distillery is notable for a substantial battery of traditional Charentais pot stills. This combination of vineyard ownership, high distilling capacity and family cellar management enables the producer to work across several Cognac crus while retaining direct technical control over spirit production. Its identity is grounded less in a single famous château than in six generations of practical distillation and cellar work.',
  description_ko = '막심 트리욜(Maxime Trijol)은 1859년 생마르시알쉬르네(Saint-Martial-sur-Né)에 가문의 첫 증류기를 설치한 것을 출발점으로 삼는 가족 경영 코냑 생산자입니다. 6세대에 걸쳐 포도 재배와 증류에서 출발해 오늘날에는 포도밭 관리, 증류, 숙성, 병입을 자체적으로 수행하는 수직계열형 하우스로 발전했습니다. 역사적으로 원액 중개와 전문 증류 업무를 함께 수행하면서 증류 기술을 축적했고, 현재는 다수의 전통 샤랑테식 구리 단식 증류기를 운용하는 상당한 증류 역량으로도 알려져 있습니다. 자가 포도밭과 높은 증류 능력, 가족이 직접 관리하는 숙성고를 동시에 보유하기 때문에 여러 크뤼의 원액을 다루면서도 증류 단계부터 품질을 세밀하게 통제할 수 있습니다. 특정 샤토의 상징성보다는 세대를 거쳐 축적된 실무적 증류·숙성 기술 자체가 막심 트리욜의 핵심 자산입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 623;

-- id=624 | Croizet
UPDATE producer
SET
  founded_year = 1805,
  name_en = 'Croizet',
  name_ko = '크루아제',
  search_keywords = 'Croizet, Cognac Croizet, Maison Croizet, Saint-Meme-les-Carrieres, 크루아제, 크로아제',
  website = 'https://www.croizet.fr/',
  description_en = 'Croizet was founded in 1805 by Simon Croizet in Saint-Même-les-Carrières and is one of the historic houses associated with Grande Champagne. The house draws on vineyard holdings and long-aged stocks, including cellars linked to the area’s extensive Turonian limestone quarries, whose stable environment is well suited to maturation. Croizet’s archives and family activity pre-date the formal founding, and the house has highlighted an eight-generation lineage of cellar expertise as well as historical involvement in rebuilding vineyards after the phylloxera crisis. Its estates include Grande Champagne properties such as Château de l’Épine and Domaine des Couronnes de Douvesse, giving the modern producer a concrete agricultural base in addition to its merchant-house history. Croizet is also associated with old vintage Cognacs, a category requiring strict traceability and official control, which reflects the importance of historical stocks and cellar record-keeping to the house.',
  description_ko = '크루아제(Croizet)는 시몽 크루아제(Simon Croizet)가 1805년 Saint-Même-les-Carrières에서 설립한 역사적인 코냑 하우스로, 특히 그랑드 샹파뉴와 깊은 연관을 갖고 있습니다. 이 지역의 투로니안 석회암 지층에 형성된 지하 채석장과 연결된 숙성 환경, 오래된 원액 재고, 포도원 자산을 생산 기반으로 활용해 왔습니다. 공식 설립 이전으로 이어지는 가문 자료와 8세대에 걸친 셀러 관리 전통을 강조하며, 19세기 필록세라 이후 포도밭 복구 과정에도 가문이 관여한 역사로 알려져 있습니다. 오늘날에는 Château de l’Épine, Domaine des Couronnes de Douvesse 등 그랑드 샹파뉴의 구체적인 포도원 기반을 갖추어 단순한 상표형 네고시앙을 넘어 농업적 뿌리를 유지합니다. 빈티지 코냑처럼 출처·연도 추적과 엄격한 관리가 필요한 오래된 원액 분야에서도 존재감이 있어, 역사적 재고와 셀러 기록 관리 능력이 하우스 가치의 중요한 부분을 이룹니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 624;

-- id=625 | Château de Montifaud
UPDATE producer
SET
  founded_year = 1866,
  name_en = 'Château de Montifaud',
  name_ko = '샤토 드 몽티포',
  search_keywords = 'Chateau de Montifaud, Château de Montifaud, Montifaud, Vallet, Vallet Family, 샤토 드 몽티포, 몽티포',
  website = 'https://www.montifaud.com/',
  description_en = 'Château de Montifaud is an independent family Cognac estate whose roots are tied to the Vallet family’s nineteenth-century vineyards and whose continuous family ownership is commonly dated from 1866. Six generations have developed the estate, with a particular specialization in Petite Champagne while also working vineyards in Grande Champagne. Montifaud is a classic grower-producer: the family manages the vines, distils its wines, ages the eaux-de-vie in its own cellars and bottles under its own name, keeping the production chain close to the estate. The house places considerable importance on continuity between generations, including the transfer of cellar stocks and blending knowledge long before each new family member formally takes over. Its producer identity is therefore based on estate control and family succession rather than large-scale external sourcing, with the chalky Champagne crus forming the foundation of its style and long-ageing potential.',
  description_ko = '샤토 드 몽티포(Château de Montifaud)는 발레(Vallet) 가문의 19세기 포도재배 역사에서 출발해, 일반적으로 1866년부터 이어진 가족 소유 전통을 기준으로 소개되는 독립 코냑 에스테이트입니다. 6세대에 걸쳐 발전했으며 특히 프티트 샹파뉴(Petite Champagne)를 전문 영역으로 삼는 동시에 그랑드 샹파뉴에도 포도밭을 보유합니다. 포도 재배, 와인 양조, 샤랑테식 증류, 자체 숙성고에서의 장기 숙성, 병입까지 가족이 직접 관리하는 전형적인 그로워-프로듀서 구조를 갖춥니다. 세대 교체 과정에서 단순히 경영권만 넘기는 것이 아니라 오래된 원액 재고와 블렌딩 판단을 오랜 기간 함께 공유하며 기술을 이전하는 가족 승계 방식도 중요한 특징입니다. 대규모 외부 원액 조달보다 자가 포도밭과 자체 생산 체계를 중심에 두고, 샹파뉴 크뤼의 석회질 테루아와 장기 숙성 잠재력을 하우스 정체성으로 연결합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 625;

-- id=626 | Paul Giraud
UPDATE producer
SET
  founded_year = 1635,
  name_en = 'Paul Giraud',
  name_ko = '폴 지로',
  search_keywords = 'Paul Giraud, Cognac Paul Giraud, Giraud, Bouteville, 폴 지로, 폴지로',
  website = 'https://www.cognac-paulgiraud.com/',
  description_en = 'Paul Giraud is an independent family estate in Bouteville, in the heart of Grande Champagne, whose family vineyard history is documented by the house from 1635. Across eleven generations—and several family members named Paul—the estate has remained closely tied to the same Premier Cru landscape. Today it farms around 50 hectares, principally Ugni Blanc, and controls the chain from grape growing through distillation, ageing and bottling. A crucial distinction in its history is that the family’s agricultural roots are much older than its direct commercial presence: the Girauds began marketing Cognac independently under their own name in the 1970s. Paul Giraud is therefore best understood as an old winegrowing family that became a producer-bottler, with deep stocks and long practical experience of Grande Champagne rather than a house created as a nineteenth- or twentieth-century trading company.',
  description_ko = '폴 지로(Paul Giraud)는 그랑드 샹파뉴 중심부의 부트빌(Bouteville)에 위치한 독립 가족 경영 에스테이트로, 하우스가 제시하는 가문의 포도재배 역사는 1635년까지 거슬러 올라갑니다. 11세대에 걸쳐 같은 프리미에 크뤼 지역과 긴밀하게 연결되어 왔고, 가문에는 여러 명의 ‘Paul Giraud’가 이어져 이름 자체가 생산자 계보를 나타냅니다. 현재 약 50헥타르의 포도밭에서 주로 위니 블랑(Ugni Blanc)을 재배하며 포도 재배, 증류, 숙성, 병입을 직접 관리합니다. 다만 ‘가문의 농업적 기원’과 ‘자체 브랜드 상업화’는 구분해야 하며, 폴 지로가 자기 이름으로 코냑을 독립 판매하기 시작한 것은 1970년대입니다. 즉 오래된 네고시앙 하우스라기보다 수세기 동안 그랑드 샹파뉴를 경작해 온 가족이 자체 병입 생산자로 발전한 사례로 보는 것이 가장 정확합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 626;

-- id=627 | Vallein Tercinier
UPDATE producer
SET
  founded_year = 1850,
  name_en = 'Vallein Tercinier',
  name_ko = '발랭 테르시니에',
  search_keywords = 'Vallein Tercinier, Vallein-Tercinier, Cognac Vallein Tercinier, Domaine des Forges, 발랭 테르시니에, 발렌 테르시니에',
  website = 'https://www.cognac-tercinier.com/',
  description_en = 'Vallein Tercinier is a family Cognac house at Domaine des Forges in Chermignac, with family roots in the Saintonge extending to the fifteenth century and a trading-house activity established around 1850 by Georges Vallein. The family had acquired Domaine des Forges earlier, in 1791, so the producer’s story combines an agricultural estate with a later formal négociant business. Now in its sixth generation as a Cognac producer, Vallein Tercinier cultivates vines, distils and ages its own eaux-de-vie while also maintaining the blending and selection capabilities of a merchant house. In the modern Cognac world it has earned particular attention for old single-cask and vintage releases that identify cru, year and provenance with unusual precision. That focus reflects the house’s strongest asset: deep family cellars and documentary knowledge of mature eaux-de-vie, joined to continuing vineyard and distillation activity rather than a purely archival bottling business.',
  description_ko = '발랭 테르시니에(Vallein Tercinier)는 셰르미냑(Chermignac)의 Domaine des Forges를 기반으로 하는 가족 코냑 하우스입니다. 가문의 생통주(Saintonge) 지역 뿌리는 15세기까지 거슬러 올라가며, 1791년에 Domaine des Forges를 인수한 뒤 조르주 발랭(Georges Vallein)이 1850년경 본격적인 코냑 상업 활동을 구축했습니다. 현재 6세대 생산자로서 포도 재배와 증류, 자체 숙성을 수행하는 동시에 네고시앙 하우스의 원액 선별·블렌딩 능력도 갖춘 복합적인 구조입니다. 최근 코냑 애호가 시장에서는 오래된 싱글 캐스크와 빈티지 원액을 크뤼, 증류연도, 출처와 함께 구체적으로 제시하는 병입으로 특히 높은 인지도를 얻었습니다. 이는 단순히 오래된 재고를 보유했다는 뜻을 넘어, 가족 숙성고의 깊은 원액 자산과 문서화된 provenance, 현재도 이어지는 포도밭·증류 활동이 함께 작동하는 하우스임을 보여 줍니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 627;

-- id=628 | Grosperrin
UPDATE producer
SET
  founded_year = 1992,
  name_en = 'Grosperrin',
  name_ko = '그로스페랭',
  search_keywords = 'Grosperrin, Cognac Grosperrin, Maison Grosperrin, Jean Grosperrin, Guilhem Grosperrin, 그로스페랭, 그로스페린',
  website = 'https://cognac-grosperrin.com/',
  description_en = 'Grosperrin is a relatively young independent Cognac house built around the preservation and precise presentation of old, provenance-rich eaux-de-vie. Jean Grosperrin began distilling in 1981, arrived in Cognac in 1991 and became a rural broker in 1992, a role that gave him unusual access to farmers’ cellars and inherited family stocks. By the end of the 1990s he was purchasing old casks and bottling them under the Grosperrin name; his son Guilhem took over the business in 2004 and continued the same terroir- and origin-focused approach. Rather than creating a uniform global house style through heavy blending, Grosperrin often highlights individual crus, villages, vintages and cellar histories, with careful documentation of where a spirit came from. The house’s modern importance lies in treating mature Cognac almost as an archive of regional agriculture, bringing small parcels and forgotten stocks to market while retaining their identity.',
  description_ko = '그로스페랭(Grosperrin)은 오래되고 출처가 명확한 오드비(eaux-de-vie)를 발굴해 테루아와 이력을 가능한 한 그대로 드러내는 데 초점을 둔 비교적 젊은 독립 코냑 하우스입니다. 장 그로스페랭(Jean Grosperrin)은 1981년 증류를 시작했고 1991년 코냑 지역에 들어온 뒤 1992년 농촌 원액 중개인으로 활동하면서 소규모 재배농가의 숙성고와 가족이 물려받은 오래된 원액에 접근할 수 있었습니다. 1990년대 말부터 오래된 캐스크를 직접 구입해 Grosperrin 이름으로 병입했으며, 2004년 아들 기옘(Guilhem)이 사업을 이어받았습니다. 대규모 블렌딩으로 하나의 균일한 글로벌 하우스 스타일을 만드는 것보다 크뤼, 마을, 빈티지, 저장 이력을 구체적으로 밝히는 병입을 중시합니다. 지역 농업과 증류 역사가 담긴 오래된 코냑을 일종의 ‘액체 아카이브’로 보존하고 시장에 다시 소개하는 역할이 그로스페랭의 가장 뚜렷한 정체성입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 628;

-- id=629 | ABK6
UPDATE producer
SET
  founded_year = 2005,
  name_en = 'ABK6',
  name_ko = 'ABK6',
  search_keywords = 'ABK6, ABK6 Cognac, Abecassis, Domaines Francis Abécassis, Domaines Francis Abecassis, Francis Abecassis, 아베카시스, 에이비케이식스, ABK6 코냑',
  website = 'https://www.abk6-cognac.com/',
  description_en = 'ABK6 is the flagship Cognac brand created in 2005 by Francis Abécassis, its name being a phonetic compression of the Abécassis family name. The producer is built around the concept of “Single Estate Cognac”: Domaines Francis Abécassis controls large vineyard holdings across several estates and manages the major stages of production—viticulture, winemaking, distillation, ageing and blending—within the family organization. The group’s vineyards extend across important Cognac crus, including Fins Bois, Petite Champagne and Grande Champagne, allowing the team to emphasize differences in terroir while retaining estate control. It also operates multiple cellars and substantial barrel stocks and has pursued environmental certification and lower-impact vineyard practices. ABK6 is therefore not an old merchant house revived as a label, but a modern estate-based project designed from the outset to connect scale, traceable vineyard origin and integrated production.',
  description_ko = 'ABK6는 프란시스 아베카시스(Francis Abécassis)가 2005년에 만든 코냑 브랜드로, 이름은 Abécassis라는 성을 발음상 압축해 표현한 것입니다. 생산 기반인 Domaines Francis Abécassis는 ‘Single Estate Cognac’ 개념을 핵심으로 내세우며, 대규모 포도원 자산을 바탕으로 포도 재배, 양조, 증류, 숙성, 블렌딩의 주요 공정을 가족 조직 안에서 직접 관리합니다. 포도밭은 팽 부아, 프티트 샹파뉴, 그랑드 샹파뉴 등 서로 다른 크뤼에 걸쳐 있어 각 테루아의 차이를 표현하면서도 원료의 추적 가능성과 생산 통제력을 유지할 수 있습니다. 다수의 숙성고와 큰 원액 재고를 운용하고 환경 인증과 포도밭의 저충격 관리에도 지속적으로 투자해 왔습니다. 따라서 ABK6는 오래된 네고시앙 상표를 현대적으로 재포장한 브랜드라기보다, 처음부터 ‘규모 있는 자가 포도원 + 완전한 생산 통제 + 테루아 표시’를 목표로 설계된 현대적인 에스테이트형 코냑 프로젝트에 가깝습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 629;

-- id=630 | Dudognon
UPDATE producer
SET
  founded_year = 1776,
  name_en = 'Dudognon',
  name_ko = '뒤도뇽',
  search_keywords = 'Dudognon, Cognac Dudognon, Maison Dudognon, Domaine Dudognon, 뒤도뇽, 두도뇽',
  website = 'https://maisondudognon.com/',
  description_en = 'Dudognon is a small independent family estate in Grande Champagne whose winegrowing and distilling tradition is dated by the family to 1776. The producer is strongly vertically integrated: grapes are grown on the estate, the wines are distilled by the family and the resulting eaux-de-vie are matured in its own cellars before bottling. Dudognon is especially associated with traditional, hands-on production, including wood-fired Charentais distillation and long, patient oak ageing rather than a high-volume merchant model. Its position in Grande Champagne gives the house access to the chalk-rich Premier Cru fruit prized for slow development and long maturation. The house is best understood as a grower-distiller whose reputation comes from continuity of craft and control of raw material, not from mass-market scale or extensive external blending.',
  description_ko = '뒤도뇽(Dudognon)은 가문이 1776년부터 이어졌다고 밝히는 그랑드 샹파뉴의 소규모 독립 가족 에스테이트입니다. 포도 재배부터 와인 양조, 가족의 직접 증류, 자체 숙성고에서의 숙성, 병입까지 한 생산자가 관리하는 수직계열 구조가 매우 뚜렷합니다. 특히 전통적인 샤랑테식 증류기를 장작불로 가열하는 방식과 긴 오크 숙성을 고수하는 등, 대량 생산형 네고시앙보다 손이 많이 가는 전통 공정을 강조합니다. 그랑드 샹파뉴의 석회질 토양에서 얻은 원료는 천천히 발달하며 장기 숙성에 적합한 원액을 만드는 데 중요한 기반이 됩니다. 뒤도뇽의 명성은 거대한 브랜드 규모보다 원료부터 증류까지 직접 통제하는 그로워-디스틸러 구조와 세대를 이어 온 작업 방식의 연속성에서 나옵니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 630;

-- id=631 | Audry
UPDATE producer
SET
  founded_year = 1878,
  name_en = 'Audry',
  name_ko = '오드리',
  search_keywords = 'Audry, Cognac Audry, Maison Audry, Audry Cognac, 오드리, 오드리 코냑',
  website = 'https://cognac-audry.com/',
  description_en = 'Maison Audry was founded in 1878 and presents itself as a five-generation family Cognac house devoted to long maturation and careful blending. Rather than sourcing across every cru, Audry states that its Cognacs are made exclusively from eaux-de-vie of Grande Champagne and Petite Champagne, the two chalk-rich Champagne crus at the center of the appellation’s long-ageing tradition. The house deliberately matures many components well beyond the legal minimums, treating old stocks and the cellar master’s blending work as the principal means of creating its elegant, fine-textured style. Audry uses the language of “haute couture” Cognac to describe this small-scale, selection-driven approach. The producer’s identity is therefore less about owning a very large vineyard estate and more about maintaining family stocks, selecting high-quality Champagne eaux-de-vie and allowing time in cellar to do a large part of the work.',
  description_ko = '오드리(Audry)는 1878년에 설립되어 5세대에 걸쳐 이어진 가족 코냑 하우스로, 장기 숙성과 세밀한 블렌딩을 생산 철학의 중심에 두고 있습니다. 공식적으로 오드리 코냑은 그랑드 샹파뉴와 프티트 샹파뉴 원액만을 사용하며, 코냑 전역의 모든 크뤼를 폭넓게 섞기보다 석회질이 강하고 장기 숙성 잠재력이 높은 두 샹파뉴 크뤼에 집중합니다. 법정 최소 숙성기간을 크게 넘겨 숙성한 원액을 다수 활용하고, 오래된 가족 재고와 셀러 마스터의 선별·블렌딩을 통해 우아하고 섬세한 하우스 스타일을 만듭니다. 스스로 ‘오트 쿠튀르(haute couture) 코냑’이라는 표현을 사용할 만큼 대량 생산보다는 선택과 시간에 가치를 둡니다. 즉 대규모 자가 포도밭의 면적보다 고품질 샹파뉴 원액의 확보, 오래된 숙성 재고, 세대 간 블렌딩 감각이 핵심 자산인 하우스입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 631;

-- id=632 | DEAU Cognac
UPDATE producer
SET
  founded_year = 1685,
  name_en = 'DEAU Cognac',
  name_ko = '도 코냑',
  search_keywords = 'DEAU, DEAU Cognac, Deau, Cognac Deau, Distillerie des Moisans, Moisans, Bru Legaret, 도, 도 코냑, 데오 코냑',
  website = 'https://www.deaucognac.com/',
  description_en = 'DEAU Cognac is the brand of a family production complex centered on the Distillerie des Moisans at Sireuil, on the Charente. The house traces its family winegrowing story to 1685, when Louis Deau settled in the region, while the modern distillery infrastructure was developed much later by the Bru family, particularly from the 1960s. Today the Bru-Legaret family continues the business, combining vineyard holdings with a large traditional distillery, multiple Charentais pot stills, extensive barrel stocks and maturation cellars. This distinction matters because DEAU should not be confused with the Boinaud family, which is associated with De Luze rather than DEAU. As a producer, DEAU is best described as a modern family estate-distillery built on an older local lineage: it controls a meaningful share of its grape supply and spirit production and uses the Moisans site as the technical heart of blending and ageing.',
  description_ko = '도 코냑(DEAU Cognac)은 샤랑트 강변 Sireuil의 Distillerie des Moisans를 중심으로 운영되는 가족 생산 체계의 코냑 브랜드입니다. 하우스는 루이 도(Louis Deau)가 이 지역에 정착한 1685년을 가문의 포도재배 역사 기원으로 제시하지만, 오늘날의 대규모 증류 시설은 훨씬 뒤인 1960년대 이후 Bru 가문이 발전시킨 현대적 기반입니다. 현재 Bru-Legaret 가족이 사업을 이어가며 자체 포도밭, 다수의 전통 샤랑테식 증류기, 대규모 캐스크 재고와 숙성고를 결합해 생산합니다. 중요한 메타데이터상 주의점은 DEAU가 부아노(Boinaud) 가문 브랜드가 아니라는 것입니다. 부아노는 De Luze와 직접 연결되며, DEAU의 생산 기반은 Distillerie des Moisans와 Bru-Legaret 계보에 있습니다. 따라서 DEAU는 오래된 지역 가족사와 현대적인 가족 소유 증류소가 결합된 에스테이트-디스틸러리형 하우스로 설명하는 것이 정확합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 632;

-- id=633 | Jean-Luc Pasquet
UPDATE producer
SET
  founded_year = 1730,
  name_en = 'Jean-Luc Pasquet',
  name_ko = '장-뤽 파스케',
  search_keywords = 'Jean-Luc Pasquet, Cognac Pasquet, Jean Luc Pasquet, Pasquet, Domaine Pasquet, 장뤽 파스케, 장-뤽 파스케, 파스케 코냑',
  website = 'https://cognac-pasquet.com/',
  description_en = 'Jean-Luc Pasquet is an independent family Cognac producer in Éraville, Grande Champagne, whose vineyard lineage is documented into the eighteenth century; the estate itself commonly cites 1730 as part of that family continuity. The modern producer identity, however, was shaped much later: Jean-Luc Pasquet began developing the estate independently around 1970 and created the Cognac Pasquet brand in 1977. The family became an early adopter of organic viticulture in Cognac, experimenting in the 1990s and ultimately building a certified-organic production model for its own vineyards. Today the house, led by the next generation, combines estate Cognac with carefully sourced “family treasure” releases from other small growers, usually with unusually transparent information about producer, cru and origin. Pasquet therefore represents both sides of contemporary artisan Cognac: an organic Grande Champagne grower-distiller and an independent bottler preserving the identities of small family stocks.',
  description_ko = '장-뤽 파스케(Jean-Luc Pasquet)는 그랑드 샹파뉴의 Éraville에 자리한 독립 가족 코냑 생산자로, 포도밭의 가족 계보는 18세기까지 이어지며 에스테이트는 1730년을 중요한 역사 기준으로 제시합니다. 다만 오늘날 우리가 아는 생산자와 브랜드의 직접적인 형성은 훨씬 뒤로, Jean-Luc Pasquet가 1970년경 독립적인 농장 운영을 본격화하고 1977년에 Cognac Pasquet 브랜드를 만든 시점과 구분해야 합니다. 1990년대부터 코냑 지역에서 비교적 일찍 유기농 포도재배를 시험·도입해 자체 포도밭의 유기농 생산 체계를 구축한 선구적 소규모 생산자이기도 합니다. 현재 다음 세대는 자가 그랑드 샹파뉴 코냑과 함께 다른 소규모 농가의 오래된 원액을 생산자·크뤼·출처를 투명하게 밝혀 병입하는 ‘Trésors de Famille’ 성격의 프로젝트도 전개합니다. 유기농 그로워-디스틸러와 독립 보틀러의 두 역할을 동시에 수행한다는 점이 현대 Pasquet의 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 633;

-- id=593 | Hennessy
UPDATE producer
SET
  founded_year = 1765,
  name_en = 'Hennessy',
  name_ko = '헤네시',
  search_keywords = 'Hennessy, Jas Hennessy & Co, Maison Hennessy, Hennessy Cognac, Jas Hennessy, 헤네시, 헤네시 코냑',
  website = 'https://www.hennessy.com/',
  description_en = 'Hennessy was founded in Cognac in 1765 by Richard Hennessy, an Irish-born officer who settled in France and established what became one of the world’s defining Cognac houses. Over more than 260 years the company developed a global trading network, very large reserves of aged eaux-de-vie and a highly structured system of grower relationships, tasting and blending. A central part of its technical continuity is the Fillioux family’s long association with the role of master blender, extending across eight generations, alongside Hennessy’s formal tasting committee and extensive cellar stocks. Hennessy is not a single-estate producer; its scale depends on selecting eaux-de-vie from across the Cognac appellation and assembling them to reproduce house style consistently over time. The house’s significance lies both in production and in industry history: it helped make Cognac an international luxury spirit and remains a benchmark for large-scale blending, ageing logistics, sensory selection and long-term partnerships with the region’s growers.',
  description_ko = '헤네시(Hennessy)는 아일랜드 출신 군인이었던 리처드 헤네시(Richard Hennessy)가 프랑스에 정착한 뒤 1765년 코냑에서 설립한 세계적인 코냑 하우스입니다. 260년이 넘는 기간 동안 국제 유통망, 방대한 장기 숙성 오드비 재고, 재배농가와의 체계적인 파트너십, 전문 테이스팅·블렌딩 시스템을 구축하며 코냑을 세계적 고급 증류주로 확산시키는 데 큰 역할을 했습니다. 생산 기술의 연속성에서는 8세대에 걸쳐 마스터 블렌더 역할과 연결된 필리우(Fillioux) 가문의 역사, 정기적인 테이스팅 위원회, 매우 큰 숙성고 재고가 핵심입니다. 단일 포도원 코냑이 아니라 코냑 아펠라시옹 전역에서 다양한 원액을 선별해 매년 일관된 하우스 스타일을 재현하는 대형 블렌딩 하우스이며, 그 규모 자체가 숙성 재고 관리·감각 평가·장기 농가 관계를 고도로 시스템화하게 만들었습니다. 헤네시는 브랜드 규모뿐 아니라 코냑 산업의 글로벌화와 현대적 대형 하우스 운영 모델을 대표하는 생산자입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 593;

-- id=594 | Rémy Martin
UPDATE producer
SET
  founded_year = 1724,
  name_en = 'Rémy Martin',
  name_ko = '레미 마르탱',
  search_keywords = 'Remy Martin, Rémy Martin, Remy Martin Cognac, Maison Rémy Martin, Fine Champagne Cognac, 레미 마르탱, 레미 마틴, 레미마르탱',
  website = 'https://www.remymartin.com/',
  description_en = 'Rémy Martin was founded in 1724 by a young winegrower of the same name and has built its house identity around the Champagne crus of Cognac. A defining decision was the long-term focus on Fine Champagne Cognac, made from Grande Champagne and Petite Champagne eaux-de-vie with at least half from Grande Champagne; this has tied the brand closely to chalk-rich terroirs prized for long ageing. The house works through extensive partnerships with winegrowers and the Alliance Fine Champagne, combining agricultural relationships with its own distillation, maturation, tasting and blending expertise. Historical milestones include the royal permission granted in 1738 to plant additional vines and the development of Grande Champagne Cognacs during the nineteenth century. Rather than presenting itself as a single estate, Rémy Martin is a specialist large house whose continuity rests on grower partnerships, deep aged stocks and a very deliberate restriction of its sourcing universe to the two Champagne crus.',
  description_ko = '레미 마르탱(Rémy Martin)은 동명의 젊은 포도재배자가 1724년에 시작한 코냑 하우스로, 설립 초기부터 현재까지 코냑의 샹파뉴 크뤼와 강하게 연결된 정체성을 발전시켜 왔습니다. 가장 중요한 특징은 그랑드 샹파뉴와 프티트 샹파뉴 원액으로 구성되고 그중 그랑드 샹파뉴가 최소 절반 이상이어야 하는 ‘파인 샹파뉴(Fine Champagne) 코냑’에 장기간 집중해 왔다는 점입니다. 하우스는 다수의 재배농가 및 Alliance Fine Champagne와 장기 파트너십을 구축해 원료 기반을 확보하고, 자체 증류·숙성·테이스팅·블렌딩 역량으로 일관된 스타일을 만듭니다. 1738년 루이 15세로부터 추가 포도 식재 허가를 받은 역사와 19세기 그랑드 샹파뉴 코냑 개발 등도 하우스 서사의 중요한 부분입니다. 단일 에스테이트가 아니라 두 샹파뉴 크뤼에 원료 범위를 의도적으로 집중한 ‘전문화된 대형 하우스’라는 점이 레미 마르탱을 이해하는 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 594;

-- id=595 | Martell
UPDATE producer
SET
  founded_year = 1715,
  name_en = 'Martell',
  name_ko = '마르텔',
  search_keywords = 'Martell, Maison Martell, Martell Cognac, Jean Martell, 마르텔, 마텔 코냑',
  website = 'https://www.martell.com/',
  description_en = 'Martell was founded in 1715 by Jean Martell and is the oldest of Cognac’s major historic houses. From its base on the Charente it developed international trade early and built a distinctive production style around careful sourcing, distillation and maturation. Martell is particularly known for distilling clear wines from which the heavy lees have been removed and for ageing in fine-grained French oak, choices the house links to finesse, aromatic clarity and elegant texture. The house has long worked with several Cognac crus, with Borderies holding a special place in its history and blending vocabulary. Over three centuries, Martell has grown from an eighteenth-century merchant enterprise into a global producer while retaining a clearly articulated technical house style. Its importance lies in the combination of exceptional age, early export history, large blending reserves and production choices that remain deliberately different from houses that favor full-lees distillation.',
  description_ko = '마르텔(Martell)은 장 마르텔(Jean Martell)이 1715년에 설립한 코냑의 대표적 역사 하우스 가운데 가장 오래된 곳입니다. 샤랑트 강을 기반으로 일찍부터 국제 교역을 발전시켰고, 다양한 크뤼의 원액을 선별·숙성·블렌딩하면서도 분명한 기술적 하우스 스타일을 구축했습니다. 특히 무거운 리(lees)를 제거해 비교적 맑은 와인을 증류하고, 결이 고운 프랑스산 오크통을 숙성에 사용하는 방식을 강조하며 이를 섬세함과 향의 선명도, 우아한 질감과 연결합니다. 여러 크뤼를 활용하지만 보르드리(Borderies)는 마르텔의 역사와 블렌딩 언어에서 특별한 위치를 차지합니다. 18세기 상인 기업에서 세계적 하우스로 성장한 지금도, 장기 숙성 재고와 대규모 블렌딩 능력뿐 아니라 ‘리와 오크의 선택’처럼 다른 하우스와 구별되는 구체적인 생산 판단을 유지한다는 점이 중요합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 595;

-- id=596 | Courvoisier
UPDATE producer
SET
  founded_year = 1828,
  name_en = 'Courvoisier',
  name_ko = '쿠르부아지에',
  search_keywords = 'Courvoisier, Cognac Courvoisier, Maison Courvoisier, Felix Courvoisier, Félix Courvoisier, 쿠르부아지에, 꾸르부아지에',
  website = 'https://www.courvoisier.com/',
  description_en = 'Courvoisier’s modern official history distinguishes the predecessor Gallois cellars, established in Paris in 1796, from the Cognac house itself, which Félix Courvoisier and Jules Gallois established in Jarnac in 1828. This makes 1828 the most defensible founding year for the producer as a dedicated Cognac house, although older references sometimes use other dates from the family’s earlier trade. From Jarnac the company developed a major international brand based on long-term relationships with growers, careful selection of eaux-de-vie from several crus and extensive maturation and blending stocks. Courvoisier’s historical image is strongly associated with nineteenth-century France and the Napoleonic era, but its production identity is that of a large multi-cru blending house rather than a single estate. In the twenty-first century it remains one of Cognac’s globally recognized major houses, with the Jarnac headquarters and cellar system at the center of its continuity.',
  description_ko = '쿠르부아지에(Courvoisier)의 최신 공식 연혁은 1796년 파리에 세워진 Gallois의 선행 와인·주류 사업과, 펠릭스 쿠르부아지에(Félix Courvoisier)와 쥘 갈루아(Jules Gallois)가 1828년 자르낙(Jarnac)에 설립한 ‘코냑 하우스 자체’를 구분합니다. 따라서 생산자 설립연도라는 의미에서는 1828년이 가장 직접적인 기준이며, 과거 자료에 보이는 다른 연도는 이전 가족 사업의 역사와 섞여 이해할 필요가 있습니다. 자르낙을 중심으로 재배농가와 장기 관계를 구축하고 여러 크뤼의 오드비를 선별해 대규모 숙성·블렌딩 체계를 발전시켰으며, 단일 에스테이트보다 다지역 원액을 조합하는 대형 하우스 구조가 본질입니다. 19세기 프랑스와 나폴레옹 시대를 연상시키는 브랜드 서사가 매우 유명하지만, 생산자 관점에서는 자르낙의 숙성 기반, 깊은 재고, 원액 선별 및 반복 가능한 하우스 블렌드 구축 능력이 더 중요한 핵심 자산입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 596;

-- id=598 | Bisquit & Dubouché
UPDATE producer
SET
  founded_year = 1819,
  name_en = 'Bisquit & Dubouché',
  name_ko = '비스키 & 뒤부셰',
  search_keywords = 'Bisquit, Bisquit & Dubouche, Bisquit & Dubouché, Bisquit Dubouché, Cognac Bisquit, Alexandre Bisquit, 비스키, 비스키 뒤부셰, 비스키 & 뒤부셰, 비스킷 코냑',
  website = 'https://www.bisquitdubouche.com/',
  description_en = 'Bisquit & Dubouché traces its house to 1819, when Alexandre Bisquit, born into a family of distillers, founded his own Cognac business at the age of twenty. Adrien Dubouché later joined the enterprise in 1846, giving the house the double name by which it is known today. The producer’s historical narrative emphasizes meticulous distillation, including a deliberately extended distillation process intended to capture a broad aromatic spectrum, as well as an early move toward selling Cognac in branded bottles during the nineteenth century. The house became an important export brand and has passed through different corporate ownership structures over its long history, but the Bisquit & Dubouché identity continues to be built around its Jarnac-era heritage, distilling tradition and mature blending stocks. It is a classic historic merchant house rather than a single-vineyard estate.',
  description_ko = '비스키 & 뒤부셰(Bisquit & Dubouché)는 증류 가문 출신의 알렉상드르 비스키(Alexandre Bisquit)가 스무 살이던 1819년에 자신의 코냑 사업을 시작한 것을 설립 시점으로 보고 있습니다. 1846년 아드리앙 뒤부셰(Adrien Dubouché)가 사업에 합류하면서 오늘날의 두 성을 결합한 하우스 이름이 형성됐습니다. 생산 역사에서는 일반적인 공정보다 증류 시간을 길게 가져가 다양한 향 성분을 세밀하게 추출한다는 증류 철학을 강조하며, 19세기 비교적 이른 시기에 브랜드 병입 코냑을 판매한 하우스 가운데 하나로도 소개됩니다. 긴 역사 동안 소유 구조는 여러 차례 바뀌었지만, 하우스의 정체성은 19세기 자르낙 중심의 상업적 성장, 증류 기술, 숙성 원액과 블렌딩 전통에 기반합니다. 단일 포도원 생산자라기보다 다양한 원액을 선별하고 하우스 스타일로 조합해 국제 시장에 공급해 온 전형적인 역사적 네고시앙 하우스로 보는 것이 적절합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 598;

-- id=599 | Louis Royer
UPDATE producer
SET
  founded_year = 1853,
  name_en = 'Louis Royer',
  name_ko = '루이 루아예',
  search_keywords = 'Louis Royer, Cognac Louis Royer, Maison Louis Royer, Jarnac, 루이 루아예, 루이 로예, 루이 로이어',
  website = 'https://www.louis-royer.com/',
  description_en = 'Louis Royer was founded in Jarnac in 1853 by Louis Royer, a cellar master whose family’s beekeeping inspired the bee emblem that remains associated with the house. From cellars close to the Charente, the company developed as a classic Cognac merchant and blender with a strong export orientation. In its modern form the house is part of the family-owned French spirits group Terroirs Distillers and benefits from a more integrated production base, including Domaine du Ménis in Grande Champagne and distilling resources such as Distillerie d’Aumagne. This gives Louis Royer access not only to purchased eaux-de-vie but also to estate and distillation capabilities within the wider group. The producer’s identity therefore links a nineteenth-century Jarnac blending house with a contemporary vine-to-spirit infrastructure, while the bee continues to symbolize the founder’s values of patience, organization and craftsmanship.',
  description_ko = '루이 루아예(Louis Royer)는 셀러 마스터였던 루이 루아예가 1853년 자르낙(Jarnac)에서 설립한 코냑 하우스입니다. 창립자의 양봉 활동에서 유래한 ‘벌’ 문양이 지금까지 하우스를 대표하며, 샤랑트 강 인근의 숙성고를 바탕으로 전형적인 네고시앙·블렌더이자 수출 지향 코냑 하우스로 성장했습니다. 현재는 프랑스 가족 소유 주류 그룹 Terroirs Distillers의 일부로 운영되며, 그랑드 샹파뉴의 Domaine du Ménis와 Distillerie d’Aumagne 같은 그룹 내 포도원·증류 자산을 활용할 수 있어 과거보다 수직계열화된 생산 기반을 갖습니다. 즉 외부 원액 선별과 블렌딩만 수행하는 상표형 하우스가 아니라, 현대에는 포도밭과 증류 역량까지 연결된 그룹 생산 체계 안에 놓여 있습니다. 19세기 자르낙 하우스의 역사와 현대적 ‘포도에서 증류주까지’의 인프라가 결합된 형태이며, 벌 문양은 창립 이래 인내·조직성·장인정신을 상징합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 599;

-- id=600 | Meukow
UPDATE producer
SET
  founded_year = 1862,
  name_en = 'Meukow',
  name_ko = '뫼코',
  search_keywords = 'Meukow, Cognac Meukow, Maison Meukow, Meukow Panther, 뫼코, 뫼코 코냑, 메우코프, 뮤코',
  website = 'https://meukowcognac.com/',
  description_en = 'Meukow was founded on 1 August 1862 by brothers Auguste-Christophe and Gustav Meukow, originally from Silesia, after they had been sent to France in connection with the supply of Cognac to the Russian court. The house developed from this cross-European commercial background into a permanent Cognac company and later became widely recognized by the black panther that appears on its bottles. Its production model is that of a merchant-blender house: selecting eaux-de-vie from the region, maturing them in cellar and assembling them to a consistent style rather than relying on one single vineyard. Over time the company changed ownership and expanded its international distribution while preserving the Meukow name and its nineteenth-century origin story. The producer is therefore a strong example of Cognac’s historic internationalism—foreign founders, French regional production and a house style created through selection, maturation and blending for export markets.',
  description_ko = '뫼코(Meukow)는 실레지아 출신의 형제 오귀스트-크리스토프와 구스타프 뫼코가 1862년 8월 1일 설립한 코냑 하우스입니다. 두 형제는 러시아 궁정에 공급할 코냑과 관련된 임무로 프랑스에 왔다가 현지에 사업을 구축했으며, 이처럼 유럽 간 교역에서 출발한 배경이 하우스의 중요한 역사입니다. 오늘날 병에 부조된 검은 표범으로 널리 인식되지만, 생산자 구조상 핵심은 특정 단일 포도밭보다 코냑 지역의 다양한 오드비를 선별하고 숙성한 뒤 일관된 하우스 스타일로 조합하는 네고시앙·블렌더 역할입니다. 이후 소유 구조와 유통망은 변화했지만 Meukow라는 이름과 19세기 창업 스토리는 유지되었습니다. 외국인 창업자, 프랑스 코냑 지역의 생산 기반, 수출 시장을 겨냥한 숙성·블렌딩 역량이 결합된 사례로, 코냑 산업이 본래부터 국제 교역과 밀접했다는 점을 잘 보여 주는 하우스입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 600;

-- id=601 | Hine
UPDATE producer
SET
  founded_year = 1763,
  name_en = 'Hine',
  name_ko = '하인',
  search_keywords = 'Hine, Thomas Hine & Co, HINE Cognac, Maison Hine, Thomas Hine, 하인, 하인 코냑',
  website = 'https://hine.com/',
  description_en = 'Hine is a historic Jarnac Cognac house dating to 1763 and named for Thomas Hine, the Englishman whose family became central to its development. The house has built its identity around eaux-de-vie from Grande Champagne and Petite Champagne, traditional Charentais distillation and maturation in carefully selected oak. Hine is particularly known for its refined, long-aged Fine Champagne style and for an unusually strong historical relationship with the United Kingdom; it received a Royal Warrant from Queen Elizabeth II in 1962, a distinction that became part of the house’s modern heritage. Its production remains centered on selection, ageing and blending rather than a single estate vineyard, with vintage and early-landed traditions also contributing to its reputation among collectors. Hine’s character is therefore Anglo-French as well as deeply Charentais: a long-established Jarnac house whose identity combines Champagne-cru sourcing, cellar patience and an export history stretching across centuries.',
  description_ko = '하인(Hine)은 1763년으로 거슬러 올라가는 자르낙(Jarnac)의 역사적 코냑 하우스로, 영국 출신 토머스 하인(Thomas Hine)과 그 가문이 발전에 중심 역할을 하면서 오늘의 이름을 갖게 됐습니다. 생산 정체성은 그랑드 샹파뉴와 프티트 샹파뉴의 오드비, 전통 샤랑테식 증류, 엄선한 오크 숙성에 기반하며 특히 섬세하고 장기 숙성된 파인 샹파뉴 스타일로 알려져 있습니다. 영국과의 관계도 매우 깊어 1962년 엘리자베스 2세 여왕으로부터 Royal Warrant를 받은 역사가 현대 하우스 유산의 중요한 부분이 되었습니다. 단일 포도원보다 고품질 원액의 선별·숙성·블렌딩을 중심으로 운영되며, 빈티지 코냑과 영국에서 숙성한 ‘Early Landed’ 전통 등도 수집가 시장에서 하인의 독특한 위치를 만들었습니다. 프랑스 샤랑트의 생산 기반과 영국과의 수세기 교역 관계가 동시에 하우스 정체성을 형성합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 601;

-- id=602 | Baron Otard (Château de Cognac)
UPDATE producer
SET
  founded_year = 1795,
  name_en = 'Baron Otard (Château de Cognac)',
  name_ko = '바롱 오타르 (샤토 드 코냑)',
  search_keywords = 'Baron Otard, Otard, Château de Cognac, Chateau de Cognac, Château Royal de Cognac, DUSSE, D’USSÉ, 바롱 오타르, 오타르, 샤토 드 코냑',
  website = 'https://www.chateaudecognac.com/',
  description_en = 'Baron Otard was founded in 1795 when Jean-Baptiste Antoine Otard acquired the historic Château de Cognac, a fortress and royal residence on the Charente, and established his Cognac business there. The château is not merely a visitor-site backdrop: its thick stone walls and cellars close to the river create naturally stable, humid conditions that have long been used for ageing eaux-de-vie. The site remains an active center of Cognac maturation and is today associated with the Baron Otard and D’USSÉ brands under the Château de Cognac organization. As a producer, the house combines the functions of a traditional merchant-blender with a genuinely distinctive maturation environment embedded in one of Cognac’s most important historic buildings. Its identity is therefore inseparable from place—the castle, the Charente and the particular cellar climate are part of the production story, not only the branding.',
  description_ko = '바롱 오타르(Baron Otard)는 장바티스트 앙투안 오타르(Jean-Baptiste Antoine Otard)가 1795년 샤랑트 강변의 역사적 샤토 드 코냑(Château de Cognac)을 인수하고 그 안에 코냑 사업을 세우면서 시작됐습니다. 이 성은 단순한 관광·브랜드 배경이 아니라 실제 숙성 환경의 핵심입니다. 두꺼운 석벽과 강에 가까운 지하 공간이 비교적 안정적이고 습윤한 미기후를 만들어 오드비 장기 숙성에 활용되어 왔습니다. 현재도 Château de Cognac는 실제 숙성 거점으로 기능하며 Baron Otard와 D’USSÉ 브랜드가 이 역사적 시설과 연결되어 있습니다. 생산자 구조는 여러 원액을 선별·블렌딩하는 전통 하우스지만, 다른 곳과 달리 ‘어디서 숙성하는가’가 정체성에 매우 직접적으로 작용합니다. 성 자체, 샤랑트 강, 습윤한 셀러 환경이 마케팅 장치가 아니라 실제 생산 서사의 일부라는 점이 바롱 오타르를 설명하는 핵심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 602;

-- id=603 | A. Hardy
UPDATE producer
SET
  founded_year = 1863,
  name_en = 'A. Hardy',
  name_ko = 'A. 아르디',
  search_keywords = 'Hardy, A. Hardy, Hardy Cognac, Maison Hardy, Antoine Hardy, Anthony Hardy, 아르디, A. 아르디, 하디 코냑',
  website = 'https://www.hardycognac.com/',
  description_en = 'Hardy Cognac was founded in 1863 by Anthony Hardy, an English wine-and-spirit professional who settled in France, adopted the French first name Antoine and established a house that would become known for refined Cognac and decorative presentation. The Gallic cockerel became the emblem of the company and symbolizes the founder’s adopted French identity. Across five generations the family developed Hardy as a merchant, maturer and blender, with particular attention to old Cognacs and prestige cuvées rather than a single-estate model. The house has also built a distinctive place in the luxury segment through collaborations with French crystal and decorative-art makers for limited decanters, linking cellar stocks with high-end French craftsmanship. Beneath that presentation, however, Hardy remains fundamentally a Cognac house whose value comes from selection, long ageing and blending of mature eaux-de-vie accumulated over generations.',
  description_ko = 'A. 아르디(Hardy Cognac)는 영국 출신 와인·주류 전문가 앤서니 하디(Anthony Hardy)가 프랑스에 정착해 프랑스식 이름 ‘Antoine’을 사용하고 1863년에 설립한 코냑 하우스입니다. 프랑스에 대한 창립자의 애착을 상징하는 갈리아 수탉이 오랫동안 하우스 엠블럼으로 사용되어 왔습니다. 5세대에 걸쳐 가족이 네고시앙, 숙성자, 블렌더의 역할을 발전시켰으며, 단일 에스테이트보다 오래 숙성한 코냑과 프레스티지 블렌드에 강점을 두는 구조입니다. 프랑스의 크리스털·장식예술 업체와 협업한 한정 디캔터로 럭셔리 시장에서 독특한 이미지를 구축했지만, 그 바탕에는 세대에 걸쳐 축적한 고숙성 오드비의 선별, 장기 숙성, 블렌딩 능력이 있습니다. 즉 화려한 패키지는 하디의 한 측면일 뿐이며 생산자로서의 핵심 자산은 오랜 셀러 재고와 이를 조합하는 하우스 노하우입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 603;

-- id=604 | Gautier
UPDATE producer
SET
  founded_year = 1755,
  name_en = 'Gautier',
  name_ko = '고티에',
  search_keywords = 'Gautier, Cognac Gautier, Maison Gautier, Aigre, Osme, 고티에, 고띠에 코냑',
  website = 'https://cognac-gautier.com/',
  description_en = 'Maison Gautier was formally founded in 1755 and is based in Aigre, a small town north of Cognac where its cellars sit above and beside the Osme River. The house makes the local cellar environment a central part of its production story: proximity to water provides naturally humid conditions that slow evaporation patterns and influence the maturation of eaux-de-vie in oak. With more than three and a half centuries of family history behind its broader wine-and-spirit tradition, Gautier combines old merchant-house expertise with a location very different from the larger cellar complexes of Cognac and Jarnac. The company selects, ages and blends eaux-de-vie rather than operating solely as a single-vineyard estate, using the Aigre cellars as the defining physical element of its house style. Its long continuity and unusual riverside maturation environment are the two features that most clearly distinguish Gautier as a producer.',
  description_ko = '고티에(Gautier)는 1755년에 정식 설립된 코냑 하우스로, 코냑 시내보다 북쪽에 있는 작은 마을 에그르(Aigre)에서 운영됩니다. 특히 오슴(Osme) 강 위와 주변에 자리한 숙성고가 생산자 정체성의 핵심으로, 물과 가까운 환경에서 자연적으로 형성되는 높은 습도가 오크통의 증발과 오드비의 숙성 속도·질감에 영향을 준다고 하우스는 강조합니다. 더 넓은 가문의 와인·증류주 역사는 350년 이상 이어지며, 전통적인 원액 선별·숙성·블렌딩 능력과 코냑·자르낙의 대형 숙성고와는 다른 에그르의 물가 미기후를 결합해 왔습니다. 단일 포도원의 테루아만을 표현하는 에스테이트라기보다 다양한 오드비를 하우스 스타일로 조합하는 생산자지만, 숙성 장소 자체가 그 스타일을 규정하는 중요한 요소입니다. 오랜 역사와 특유의 강변 셀러 환경이 고티에를 가장 잘 설명하는 두 축입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 604;

-- id=605 | Maison Ferrand (Pierre Ferrand)
UPDATE producer
SET
  founded_year = 1989,
  name_en = 'Maison Ferrand (Pierre Ferrand)',
  name_ko = '메종 페랑 (피에르 페랑)',
  search_keywords = 'Maison Ferrand, Pierre Ferrand, Ferrand Cognac, Cognac Ferrand, Alexandre Gabriel, Château de Bonbonnet, Chateau de Bonbonnet, 메종 페랑, 피에르 페랑, 페랑 코냑',
  website = 'https://maisonferrand.com/',
  description_en = 'Maison Ferrand was founded in the Cognac region in 1989 by Alexandre Gabriel and developed around the revival of traditional, characterful spirits production. Its Cognac activity is best known through Pierre Ferrand, a house focused strongly on Grande Champagne and supported by family vineyard holdings and the Château de Bonbonnet estate. Ferrand combines estate fruit, long-term grower relationships, traditional Charentais distillation, detailed cask management and experimental maturation, including work with different oak origins and cellar conditions. Alexandre Gabriel has remained the central master blender and creative figure as Maison Ferrand expanded internationally and also developed other major spirits brands. The Cognac operation is therefore modern in corporate age but intentionally rooted in older regional practices: it seeks to control raw material and maturation closely while using the flexibility of an independent house to revisit historical techniques and explore cask influence in a highly deliberate way.',
  description_ko = '메종 페랑(Maison Ferrand)은 알렉상드르 가브리엘(Alexandre Gabriel)이 1989년 코냑 지역에서 설립한 독립 주류 회사로, 전통적인 생산 기법을 현대적으로 복원하고 개성 있는 증류주를 만든다는 방향에서 성장했습니다. 코냑 부문은 피에르 페랑(Pierre Ferrand)으로 가장 잘 알려져 있으며, 그랑드 샹파뉴를 강하게 중심에 두고 샤토 드 봉보네(Château de Bonbonnet)와 가족 포도원 기반을 활용합니다. 자가 원료와 장기 농가 관계, 전통 샤랑테식 증류, 세밀한 캐스크 관리, 다양한 오크 산지와 숙성 환경을 시험하는 적극적인 숙성 연구를 결합합니다. 창립자인 알렉상드르 가브리엘은 하우스가 국제적으로 확장된 뒤에도 마스터 블렌더이자 핵심 크리에이티브 인물로 남아 있습니다. 회사 자체는 비교적 젊지만 코냑 생산에서는 오래된 지역 관습을 의도적으로 재해석하며, 독립 하우스의 유연성을 이용해 원료와 오크, 셀러 환경의 영향을 깊게 탐구하는 것이 특징입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 605;

-- id=606 | Park (Tessendier)
UPDATE producer
SET
  founded_year = 1880,
  name_en = 'Park (Tessendier)',
  name_ko = '파크 (테상디에)',
  search_keywords = 'Cognac Park, Park Cognac, PARK, Tessendier, Distillerie Tessendier, Tessendier et Fils, Domaine du Buisson, 파크 코냑, 테상디에, 테센디에',
  website = 'https://www.park-cognac.com/',
  description_en = 'Cognac Park is produced by Distillerie Tessendier, whose family heritage begins with Gaston Tessendier’s Domaine du Buisson vineyards in Borderies in the 1880s. The family progressively deepened its expertise in distillation and ageing, and the modern business is led by fourth-generation brothers Jérôme and Lilian Tessendier, who divide cellar and blending responsibilities. The PARK brand itself is younger than the family enterprise: it was created in 1993 after Scottish entrepreneur Dominique Park met Jérôme Tessendier, and the distillery took full control of the brand in 2008. The producer therefore needs two dates in its story—1880 for Tessendier family production heritage and 1993 for the PARK brand. Today the house makes blended and single-cru Cognacs, including Borderies and Fine Champagne expressions, and combines large distilling expertise with a distinctly independent, family-managed blending operation.',
  description_ko = '파크 코냑(Cognac Park)은 Distillerie Tessendier가 생산하며, 생산 가문의 역사는 1880년대 가스통 테상디에(Gaston Tessendier)가 보르드리의 Domaine du Buisson 포도밭을 경작한 데서 출발합니다. 이후 세대를 거치며 증류와 숙성 기술을 확대했고, 현재는 4세대 형제 제롬(Jérôme)과 릴리앙(Lilian) 테상디에가 셀러와 블렌딩의 핵심 역할을 나누어 맡고 있습니다. 다만 PARK 브랜드 자체는 가문의 생산 역사보다 젊습니다. 1993년 스코틀랜드 출신 도미니크 파크(Dominique Park)와 제롬 테상디에의 협업으로 브랜드가 탄생했고, 2008년 Distillerie Tessendier가 PARK를 완전히 인수했습니다. 따라서 메타데이터에서는 ‘1880 = Tessendier 생산 가문 유산’, ‘1993 = PARK 브랜드 창설’을 구분할 필요가 있습니다. 오늘날에는 블렌디드 코냑과 보르드리·파인 샹파뉴 등 싱글 크뤼 라인을 함께 만들며, 상당한 증류 역량과 독립 가족 블렌딩 조직을 결합합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 606;

-- id=607 | Tesseron
UPDATE producer
SET
  founded_year = 1905,
  name_en = 'Tesseron',
  name_ko = '테세롱',
  search_keywords = 'Tesseron, Cognac Tesseron, Maison Tesseron, Abel Tesseron, Tesseron Cognac, 테세롱, 테세론 코냑',
  website = 'https://www.tesseroncognac.com/',
  description_en = 'Maison Tesseron was founded in 1905 by Abel Tesseron, who built the house by acquiring and ageing high-quality eaux-de-vie with a particular emphasis on the two Champagne crus. Over generations the family assembled deep stocks of mature Cognac and developed estates in Grande Champagne and Petite Champagne, giving the house both vineyard roots and a strong cellar-selection tradition. The modern company remains family-led, with Alfred Tesseron and the next generation involved in carrying the Cognac activity forward alongside the family’s wine interests. Tesseron became especially known for very old blends released as numbered “Lots,” a presentation that foregrounds the age and quality of its mature reserves rather than conventional mass-market tiers alone. The house’s strength is therefore the combination of twentieth-century family continuity, estate access in top crus and exceptional old stocks patiently preserved for long maturation and later blending.',
  description_ko = '테세롱(Tesseron)은 아벨 테세롱(Abel Tesseron)이 1905년에 설립한 가족 코냑 하우스로, 초기부터 고품질 오드비를 확보해 장기간 숙성하는 데 집중하며 특히 두 샹파뉴 크뤼와 강하게 연결되어 왔습니다. 여러 세대에 걸쳐 오래된 코냑 재고를 축적하고 그랑드 샹파뉴와 프티트 샹파뉴에 에스테이트 기반을 마련해, 포도원 접근성과 셀러 선별 능력을 함께 갖추었습니다. 오늘날에도 알프레드 테세롱(Alfred Tesseron)과 다음 세대가 가문의 와인 사업과 함께 코냑 부문을 이어 가는 가족 경영 구조입니다. 특히 매우 오래 숙성한 블렌드를 번호가 붙은 ‘Lot’ 형태로 선보이며, 일반적인 VS/VSOP/XO 등급 체계보다 오래된 재고 자체의 품질과 시대성을 전면에 드러내는 것으로 유명해졌습니다. 20세기 초부터 이어진 가족 연속성, 우수 크뤼의 포도원 기반, 장기간 보존된 희귀 고숙성 원액의 조합이 테세롱의 핵심 경쟁력입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 607;

-- id=608 | Prunier
UPDATE producer
SET
  founded_year = 1769,
  name_en = 'Prunier',
  name_ko = '프뤼니에',
  search_keywords = 'Prunier, Cognac Prunier, Maison Prunier, Jean Prunier, 프뤼니에, 프루니에, 프뤼니에 코냑',
  website = 'https://www.cognacprunier.fr/',
  description_en = 'Prunier is one of Cognac’s old family houses, but its chronology requires care. The family traces Jean Prunier’s wine and Cognac shipping activity to around 1700, while the house and the regional industry association commonly identify 1769 as the creation date of the family business. Using 1769 for the producer’s founding year therefore separates early ancestral trade from the formal house lineage. Prunier has remained particularly associated with the art of selecting and ageing eaux-de-vie in Cognac, maintaining historic cellars and a “Paradis” of rare old stocks. The company is known among specialists for vintage and single-origin bottlings as well as traditional blends, often preserving unusually detailed information about year and provenance. Its identity is that of a small, historic family merchant and maturer: not defined by one large estate, but by long cellar memory, careful cask selection and the ability to bring old regional stocks to bottle with their individuality intact.',
  description_ko = '프뤼니에(Prunier)는 코냑의 오래된 가족 하우스 가운데 하나지만 연혁을 구분해서 볼 필요가 있습니다. 가문은 장 프뤼니에(Jean Prunier)가 와인과 코냑을 선적·거래한 활동을 약 1700년까지 거슬러 설명하지만, 하우스와 지역 업계 자료는 가족 사업의 정식 창설 시점을 1769년으로 제시합니다. 따라서 생산자 `founded_year`에는 1769년을 사용하고 1700년은 선대의 초기 교역 활동으로 설명하는 것이 더 명확합니다. 프뤼니에는 역사적 숙성고와 희귀한 오래된 원액을 보관하는 ‘Paradis’를 유지하며, 원액 선별과 장기 숙성 자체를 핵심 역량으로 발전시켜 왔습니다. 일반 블렌드뿐 아니라 빈티지·단일 출처 병입에서 연도와 provenance를 자세히 보존하는 것으로 애호가들에게 잘 알려져 있습니다. 대규모 단일 에스테이트보다 오랜 셀러 기억, 캐스크 선별, 오래된 지역 재고를 개성을 살려 병입하는 능력이 본질인 소규모 역사 네고시앙입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 608;

-- id=609 | A. de Fussigny
UPDATE producer
SET
  founded_year = 1814,
  name_en = 'A. de Fussigny',
  name_ko = 'A. 드 퓌시니',
  search_keywords = 'A. de Fussigny, A de Fussigny, Fussigny, Cognac A. de Fussigny, Distillerie de Fussigny, A. 드 퓌시니, 드 퓌시니, 퓌시니',
  website = 'https://www.adefussigny.com/',
  description_en = 'A. de Fussigny is based on the banks of the Charente in a historic distillery whose origins are dated to 1814. The house makes its physical setting part of the production philosophy: riverside humidity and old stone cellars provide a slow, relatively stable environment for the maturation of eaux-de-vie. Its modern identity combines this two-century heritage with a more contemporary, design-conscious brand approach and an interest in traceable local sourcing, including organic eaux-de-vie. Rather than being defined by one vineyard estate, A. de Fussigny operates as a Cognac house that selects, matures and blends spirits while using the historic distillery and its cellar climate as a consistent technical anchor. The producer positions itself between heritage and experimentation, maintaining traditional Charentais ageing practices while developing new cuvées and sustainability-oriented sourcing within the appellation.',
  description_ko = 'A. 드 퓌시니(A. de Fussigny)는 샤랑트 강변의 역사적 증류 시설을 기반으로 하며, 공식적으로 그 장소의 기원을 1814년까지 거슬러 설명하는 코냑 하우스입니다. 강과 가까운 높은 습도, 오래된 석조 숙성고가 오드비를 천천히 비교적 안정적으로 숙성시키는 환경을 제공한다는 점을 생산 철학의 중요한 요소로 삼고 있습니다. 현대의 하우스는 약 200년의 장소적 유산을 보다 현대적인 디자인과 브랜드 감각에 결합하고, 지역 원액의 추적 가능성 및 유기농 오드비 조달에도 관심을 확대해 왔습니다. 하나의 대규모 자가 포도밭으로 규정되는 에스테이트라기보다 여러 원액을 선별·숙성·블렌딩하는 하우스이며, 역사적 증류소와 숙성고의 미기후가 기술적 중심점입니다. 전통 샤랑테식 숙성 방식을 유지하면서 새로운 큐베와 지속가능한 원료 조달을 시도하는 ‘유산과 현대성의 결합’이 현재 퓌시니의 성격입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 609;

-- id=611 | Delamain
UPDATE producer
SET
  founded_year = 1824,
  name_en = 'Delamain',
  name_ko = '들라맹',
  search_keywords = 'Delamain, Cognac Delamain, Maison Delamain, Delamain Cognac, Jarnac, 들라맹, 델라맹',
  website = 'https://www.delamain-cognac.com/',
  description_en = 'Delamain was founded in Jarnac in 1824 and has spent two centuries building a highly specialized identity around mature Grande Champagne Cognac. Unlike many large houses, Delamain does not operate its own distillery; it focuses on selecting exceptionally fine Grande Champagne eaux-de-vie from long-standing grower-distiller relationships, then ageing, reducing and blending them with great patience in its own riverside cellars. The house has traditionally concentrated on older categories rather than producing a broad entry-level range, reflecting the long maturation required for the style it seeks. Nine generations of family involvement, a strong culture of natural history and close attention to cask and cellar conditions form part of Delamain’s self-image. Its value as a producer lies precisely in specialization: rigorous sourcing from the Premier Cru and slow cellar work rather than ownership of every upstream production stage.',
  description_ko = '들라맹(Delamain)은 1824년 자르낙(Jarnac)에서 설립되어 200년 동안 성숙한 그랑드 샹파뉴 코냑에 매우 전문화된 정체성을 구축해 온 하우스입니다. 많은 대형 하우스와 달리 자체 대규모 증류소 운영을 핵심으로 삼지 않고, 오랫동안 거래해 온 재배농가·증류자에게서 뛰어난 그랑드 샹파뉴 오드비를 엄격히 선별한 뒤 샤랑트 강변의 자체 숙성고에서 천천히 숙성·도수 조정·블렌딩하는 데 역량을 집중합니다. 비교적 어린 엔트리 등급을 넓게 생산하기보다 오래 숙성된 범주에 무게를 두어, 하우스가 원하는 스타일에 필요한 시간을 생산 전략 자체에 반영합니다. 9세대에 걸친 가족 참여와 자연사에 대한 관심, 캐스크와 셀러 조건을 세심하게 관찰하는 문화도 들라맹의 하우스 철학을 형성합니다. 모든 생산 단계를 직접 소유하기보다 프리미에 크뤼 원액을 탁월하게 선별하고 오래 기다리는 ‘전문화’가 경쟁력인 생산자입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 611;

-- id=612 | Ragnaud-Sabourin
UPDATE producer
SET
  founded_year = 1850,
  name_en = 'Ragnaud-Sabourin',
  name_ko = '라뇨 사부랭',
  search_keywords = 'Ragnaud-Sabourin, Ragnaud Sabourin, Cognac Ragnaud Sabourin, Domaine de la Voute, Domaine de La Voûte, 라뇨 사부랭, 라그노 사부랭',
  website = 'https://www.cognacragnaudsabourin.fr/',
  description_en = 'Ragnaud-Sabourin is an independent family grower and négociant based at Domaine de La Voûte in Ambleville, with a house tradition dated to 1850. The family farms about 35 hectares in Grande Champagne and controls the full sequence from vineyard to eaux-de-vie, producing limited quantities rather than pursuing mass-market scale. Distillation is carried out in traditional Charentais stills with the lees, and the spirits are then matured in French oak in family cellars before blending. The house maintains unusually deep stocks relative to annual sales, which gives the cellar master freedom to age components for long periods and bottle only what is considered ready. Ragnaud-Sabourin is therefore a strong example of the Grande Champagne estate model: meaningful vineyard ownership, direct distillation, family-held stocks and a production rhythm governed by maturation rather than rapid turnover.',
  description_ko = '라뇨 사부랭(Ragnaud-Sabourin)은 앙블빌(Ambleville)의 Domaine de La Voûte를 기반으로 하며, 1850년부터 이어진 독립 가족 경영 그로워이자 네고시앙입니다. 약 35헥타르의 포도밭이 그랑드 샹파뉴에 위치하고, 포도밭에서 오드비까지 전 과정을 직접 관리하면서 대량 생산보다 제한된 수량의 고품질 코냑을 만드는 데 초점을 둡니다. 와인의 리(lees)를 포함해 전통 샤랑테식 증류기로 증류하고, 이후 가족 숙성고의 프랑스산 오크통에서 장기간 숙성한 뒤 블렌딩합니다. 연간 판매량에 비해 매우 큰 숙성 재고를 보유한다고 밝히고 있어, 시장 회전 속도보다 원액의 성숙도를 기준으로 병입 시점을 선택할 수 있는 여유가 큽니다. 자가 포도밭, 직접 증류, 가족 소유의 깊은 재고, 느린 숙성 리듬이 결합된 전형적인 그랑드 샹파뉴 에스테이트 모델입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 612;

-- id=613 | Jean Fillioux
UPDATE producer
SET
  founded_year = 1880,
  name_en = 'Jean Fillioux',
  name_ko = '장 피유',
  search_keywords = 'Jean Fillioux, Cognac Jean Fillioux, Domaine de La Pouyade, La Pouyade, Fillioux, 장 피유, 장 필리우, 장 필리유',
  website = 'https://cognac-jeanfillioux.fr/',
  description_en = 'Jean Fillioux is a small family Cognac estate founded in 1880 by Honoré Fillioux, a member of the famous Cognac blending family who established his own house after years of cellar work. In 1894 the family acquired Domaine de La Pouyade near Juillac-le-Coq, in Grande Champagne, which became the permanent base of the estate. Five generations have since cultivated the vineyards, distilled and aged Cognac there, with the modern family managing roughly 25 hectares in the Premier Cru. The house is therefore distinct from the broader Fillioux master-blender lineage associated with Hennessy: Jean Fillioux is an independent grower-producer with its own vines and cellars. Its small scale allows close control of parcels, distillation and long maturation, and the continuity of one Grande Champagne estate has become central to the recognizable Fillioux style.',
  description_ko = '장 피유(Jean Fillioux)는 유명한 코냑 블렌딩 가문 출신 오노레 필리우(Honoré Fillioux)가 오랜 셀러 경력을 바탕으로 1880년에 독립해 설립한 소규모 가족 코냑 에스테이트입니다. 1894년 가문이 그랑드 샹파뉴의 Juillac-le-Coq 인근 Domaine de La Pouyade를 인수하면서 현재까지 이어지는 생산 기반이 마련됐습니다. 이후 5세대가 같은 지역에서 포도밭을 관리하고 직접 증류·숙성했으며, 현재 약 25헥타르 규모의 프리미에 크뤼 포도원을 가족이 운영합니다. Hennessy의 마스터 블렌더 역사와 연결된 넓은 ‘Fillioux 가문’ 계보와는 구분해야 하며, Jean Fillioux 자체는 독립적인 자가 포도원 생산자입니다. 비교적 작은 규모 덕분에 구획별 포도, 증류, 장기 숙성을 밀접하게 통제할 수 있고, 한 그랑드 샹파뉴 에스테이트를 5세대가 이어 온 연속성이 하우스 스타일의 중심입니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 613;

-- id=614 | François Voyer
UPDATE producer
SET
  founded_year = 1870,
  name_en = 'François Voyer',
  name_ko = '프랑수아 부아예',
  search_keywords = 'Francois Voyer, François Voyer, Cognac François Voyer, Cognac Voyer, Domaine de Bibardies, Vaudon, 프랑수아 부아예, 프랑수아 보예, 부아예 코냑',
  website = 'https://cognac-voyer.fr/',
  description_en = 'François Voyer is a family Cognac producer rooted at the Domaine de Bibardies and associated above all with Grande Champagne. The Chauchet-Voyer family has distilled and aged Cognac since the nineteenth century, with the house commonly dating its continuous production tradition to the 1870s. Across more than five generations the family developed a grower-distiller model built on vineyard work, Charentais distillation and long cellar ageing, and old stocks in the family cellars reach back well before the formal house date. The modern operation also distinguishes its Grande Champagne Cognacs from other family vineyard activity, including Fins Bois under related labels, making clear that terroir origin is an important organizing principle. Today the producer remains family-directed and exports widely, but its core identity is still that of an estate-rooted Grande Champagne specialist whose style is created through parcel selection, distillation choices and patient maturation.',
  description_ko = '프랑수아 부아예(François Voyer)는 Domaine de Bibardies를 중심으로 하며 특히 그랑드 샹파뉴와 강하게 연결된 가족 코냑 생산자입니다. Chauchet-Voyer 가문은 19세기부터 코냑을 증류·숙성해 왔고, 지속적인 하우스 생산 전통은 일반적으로 1870년대부터로 설명됩니다. 5세대가 넘는 기간 동안 포도재배, 샤랑테식 증류, 자체 숙성고에서의 장기 숙성을 결합한 그로워-디스틸러 모델을 발전시켰으며, 가족 숙성고에는 공식 하우스 연혁보다 더 오래된 원액도 전해집니다. 현대 운영에서는 그랑드 샹파뉴 Cognac François Voyer와 가족이 다루는 다른 지역 포도원 활동을 구분해 테루아의 출처를 명확히 하는 점도 특징입니다. 국제 수출 규모가 커졌지만 핵심은 여전히 에스테이트에 뿌리 둔 그랑드 샹파뉴 전문 생산자로서, 구획별 원료 선별·증류 판단·느린 숙성을 통해 스타일을 만든다는 데 있습니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 614;

-- id=616 | Normandin-Mercier
UPDATE producer
SET
  founded_year = 1872,
  name_en = 'Normandin-Mercier',
  name_ko = '노르망댕 메르시에',
  search_keywords = 'Normandin-Mercier, Normandin Mercier, Cognac Normandin-Mercier, Maison Normandin-Mercier, Domaine de La Peraudiere, 노르망댕 메르시에, 노르망딘 메르시에',
  website = 'https://normandin-mercier.fr/',
  description_en = 'Normandin-Mercier was founded in 1872 by Édouard Normandin and is unusual among Cognac houses for being based near La Rochelle rather than in Cognac or Jarnac. The family specializes in selecting young eaux-de-vie from Grande Champagne and Petite Champagne and carrying out the crucial work of maturation in its own cellars at Domaine de La Péraudière. This makes Normandin-Mercier primarily a maturer and blender rather than a single-vineyard distiller: the house’s expertise lies in cask choice, cellar placement, time and final assembly. Successive family generations have maintained the relatively small independent structure, with the present team continuing to manage old stocks and limited releases. The producer’s identity is closely linked to the Atlantic-influenced cellar environment and to a deliberate concentration on the two Champagne crus, giving it a clear specialist profile despite not being located in the vineyard heartland itself.',
  description_ko = '노르망댕 메르시에(Normandin-Mercier)는 에두아르 노르망댕(Édouard Normandin)이 1872년에 설립했으며, 코냑이나 자르낙이 아니라 라로셸 인근을 기반으로 한다는 점에서 지리적으로 독특한 코냑 하우스입니다. 주로 그랑드 샹파뉴와 프티트 샹파뉴의 젊은 오드비를 엄선한 뒤 Domaine de La Péraudière의 자체 숙성고에서 오랜 시간 성숙시키는 데 전문성이 있습니다. 따라서 단일 포도원을 직접 증류하는 에스테이트보다 ‘숙성자·블렌더’의 성격이 강하며, 어떤 캐스크를 선택하고 어디에 배치하며 얼마나 기다릴지, 마지막에 어떤 원액을 조합할지가 하우스 기술의 핵심입니다. 여러 세대가 비교적 작은 독립 가족 구조를 유지하면서 오래된 재고와 한정 병입을 관리해 왔습니다. 대서양 영향이 느껴지는 숙성 환경과 두 샹파뉴 크뤼에 의도적으로 집중하는 원액 선택이 결합되어, 포도밭 중심지 밖에 있으면서도 매우 분명한 전문 생산자 성격을 형성합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 616;

-- id=617 | Lhéraud
UPDATE producer
SET
  founded_year = 1680,
  name_en = 'Lhéraud',
  name_ko = '레로 (르로)',
  search_keywords = 'Lheraud, Lhéraud, Cognac Lhéraud, Cognac Lheraud, Maison Lhéraud, Domaine de Lasdoux, 레로, 르로, 레로 코냑',
  website = 'https://www.cognaclheraud.com/',
  description_en = 'Lhéraud is an independent family house founded, according to its current official history, in 1680 at the Domaine de Lasdoux in Angeac-Charente. More than three centuries of family production have given the house a deep reserve of mature eaux-de-vie and a philosophy centered on time, patience and fidelity to terroir. Lhéraud remains closely involved in vineyard and cellar work and produces not only Cognac but also Pineau des Charentes, Armagnac and, more recently, other French spirits, while keeping Cognac at the heart of the family identity. The house is particularly known for old and vintage Cognacs and for a relatively uncompromising approach to long maturation and limited stocks. Its producer profile is that of a small independent family estate with international collector recognition: the value proposition is not rapid volume growth, but control, age, provenance and the accumulated cellar memory of generations at Lasdoux.',
  description_ko = '레로/르로(Lhéraud)는 현재 공식 연혁상 1680년 Angeac-Charente의 Domaine de Lasdoux에서 시작된 독립 가족 하우스입니다. 300년이 넘는 가족 생산을 통해 오래된 오드비 재고를 축적했고, ‘시간·인내·테루아에 대한 충실성’을 하우스 철학의 핵심으로 내세웁니다. 포도밭과 숙성고 운영에 가족이 밀접하게 관여하며 코냑뿐 아니라 피노 데 샤랑트, 아르마냑, 최근에는 다른 프랑스 증류주도 다루지만 생산자 정체성의 중심은 여전히 코냑입니다. 특히 오래된 빈티지와 장기 숙성 코냑, 제한된 재고를 서두르지 않고 병입하는 방식으로 수집가 시장에서 인지도가 높습니다. 빠른 물량 확대보다 자가 관리, 숙성연수, 출처, Lasdoux에서 세대별로 쌓인 셀러 기억을 가치로 삼는 소규모 독립 가족 생산자라는 점이 Lhéraud를 가장 잘 설명합니다.',
  type = 'COGNAC_HOUSE'
WHERE id = 617;

-- id=649 | Glendullan
UPDATE producer
SET
  founded_year = 1897,
  name_en = 'Glendullan',
  name_ko = '글렌듈란',
  search_keywords = 'Glendullan, 글렌듈란',
  website = 'https://www.malts.com/en-gb/distilleries/glendullan/',
  description_en = 'Glendullan is a active whisky distillery associated with Speyside, Scotland, with a historical reference date of 1897. It is currently associated with Diageo. Its spirit sits within the broad Speyside tradition, where fruit, malt sweetness and cask-driven complexity are key reference points.',
  description_ko = '글렌듈란(Glendullan)은 1897년에 설립된 스코틀랜드 스페이사이드의 위스키 증류소입니다. 더프타운의 피딕 강변에 자리하며, 현재 원액은 The Singleton of Glendullan을 비롯한 싱글 몰트와 블렌디드 스카치에 사용됩니다. 비교적 부드럽고 과일 향이 선명한 원액을 만드는 곳으로 알려져 있습니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 649;

-- id=648 | Cameronbridge
UPDATE producer
SET
  founded_year = 1824,
  name_en = 'Cameronbridge',
  name_ko = '카메론브리지',
  search_keywords = 'Cameronbridge, 카메론브리지',
  website = 'https://www.malts.com/',
  description_en = 'Cameronbridge is a active whisky distillery associated with Lowlands, Scotland, with a historical reference date of 1824. It is currently associated with Diageo. It is part of the Lowland tradition, generally associated with a lighter, floral and cereal-driven style, while retaining its own production character.',
  description_ko = '카메론브리지(Cameronbridge)은 1824년에 설립된 스코틀랜드 로우랜드의 위스키 증류소입니다. 스코틀랜드를 대표하는 대형 그레인 위스키 증류소로, 연속식 증류기를 이용해 곡물 원액을 대규모로 생산합니다. Johnnie Walker를 비롯한 여러 블렌디드 스카치의 기반 원액을 공급하며 Cameron Brig라는 싱글 그레인 브랜드와도 연결됩니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 648;

