  founded_year = 1878,
  name_en = 'Glen Spey',
  name_ko = '글렌 스페이',
  search_keywords = 'Glen Spey, 글렌 스페이',
  website = 'https://www.diageo.com/',
  description_en = 'Glen Spey is a active whisky distillery associated with Speyside, Scotland, with a historical reference date of 1878. It is currently associated with Diageo. Its spirit sits within the broad Speyside tradition, where fruit, malt sweetness and cask-driven complexity are key reference points.',
  description_ko = '글렌 스페이(Glen Spey)은 1878년에 설립된 스코틀랜드 스페이사이드의 위스키 증류소입니다. 로시스(Rothes)에 자리한 비교적 조용한 증류소로, 생산량 대부분이 블렌딩용으로 사용됩니다. 가볍고 몰티하며 은은한 견과류와 과일의 인상이 나타나는 원액으로 평가됩니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
