  description_en = 'Inchgower is a active whisky distillery associated with Speyside, Scotland, with a historical reference date of 1871. It is currently associated with Diageo. Its spirit sits within the broad Speyside tradition, where fruit, malt sweetness and cask-driven complexity are key reference points.',
  description_ko = '인치고워(Inchgower)은 1871년에 설립된 스코틀랜드 스페이사이드의 위스키 증류소입니다. 버키(Buckie) 인근 북해 연안에 자리해 스페이사이드 안에서도 해안의 영향을 느낄 수 있는 증류소입니다. 원액은 Bell’s 등 블렌드에 중요한 역할을 하며, 몰트와 견과류, 약간의 짭짤함이 어우러진 비교적 단단한 스타일로 알려져 있습니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
