-- id=181 | Royal Brackla
UPDATE producer
SET
  founded_year = 1812,
  name_en = 'Royal Brackla',
  name_ko = '로얄 브라클라',
  search_keywords = 'Royal Brackla, 로얄 브라클라',
  website = 'https://www.royalbrackla.com/',
  description_en = 'Royal Brackla is a active whisky distillery associated with Highlands, Scotland, with a historical reference date of 1812. It is currently associated with Bacardi''s Dewar''s Scotch whisky business. Its whisky reflects the broad Highland tradition, with fruit, malt, oak and texture varying according to the distillery’s individual production choices.',
  description_ko = '로얄 브라클라(Royal Brackla)은 스코틀랜드 하이랜드에 자리하고 있습니다. 1812년 설립된 하이랜드 증류소로, 1833년 윌리엄 4세에게 Royal Warrant를 받아 이름에 ‘Royal’을 사용할 수 있게 된 것으로 유명합니다. 오늘날에는 과일과 몰트의 부드러움에 셰리 캐스크 숙성의 풍부함을 더한 싱글 몰트가 중심입니다. 현재는 Bacardi의 Dewar’s 계열 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 181;

