  description_ko = '발메낙(Balmenach)은 1824년에 설립된 스코틀랜드 스페이사이드의 위스키 증류소입니다. 스페이사이드의 크롬데일(Cromdale) 부근에 자리한 오래된 증류소입니다. 싱글 몰트 공식 병입은 드물고 대부분 블렌딩용으로 쓰이며, 비교적 묵직하고 몰티하며 향신료 느낌이 있는 원액을 만듭니다. 증류소 부지에서는 Caorunn 진도 생산됩니다. 현재는 Inver House Distillers 소속으로 운영되고 있습니다.',
