  description_ko = '몰트락(Mortlach)은 1823년에 설립된 스코틀랜드 스페이사이드의 위스키 증류소입니다. 더프타운 최초의 합법 증류소로 알려져 있으며, 복잡한 증류기 연결을 이용하는 이른바 ‘2.81회 증류’ 방식이 대표적인 특징입니다. 묵직한 육향, 말린 과일, 향신료와 진한 질감 때문에 ‘The Beast of Dufftown’이라는 별명으로도 잘 알려져 있습니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
