  description_ko = '산토리 야마자키 증류소(Suntory Yamazaki Distillery)은 일본 오사카에 자리하고 있습니다. 1923년 신지로 토리가 세운 일본 최초의 본격적인 몰트 위스키 증류소로 평가됩니다. 서로 다른 형태의 증류기와 다양한 캐스크를 적극적으로 조합해 폭넓은 원액을 만들며, Yamazaki는 과일과 향신료, 미즈나라 오크의 향으로 잘 알려져 있습니다.',
