  description_ko = '오켄토션(Auchentoshan)은 1823년에 설립된 스코틀랜드 로우랜드의 위스키 증류소입니다. 글래스고 인근에 자리한 로우랜드 증류소로, 스코틀랜드에서 보기 드물게 전 생산을 3회 증류하는 것으로 유명합니다. 이 방식 덕분에 가볍고 부드러운 질감, 시트러스와 꽃, 바닐라 계열의 깔끔한 스타일이 잘 나타납니다. 현재는 Suntory Global Spirits 소속으로 운영되고 있습니다.',
