  description_ko = '불릿(Bulleit) 브랜드는 1987년에 시작됐지만 현재 켄터키 셸비빌의 전용 증류소는 2017년에 문을 열었습니다. 높은 라이 비율을 사용하는 버번 레시피로 잘 알려져 있어 바닐라와 오크의 단맛 위에 후추·계피 같은 향신료 인상이 분명합니다. 현재 브랜드와 증류 사업은 Diageo가 운영하고 있습니다.',
