  description_en = 'Tamnavulin is a historic whisky distillery that has returned to production associated with Speyside, Scotland, with a historical reference date of 1966. It is currently associated with Whyte & Mackay. Its spirit sits within the broad Speyside tradition, where fruit, malt sweetness and cask-driven complexity are key reference points.',
  description_ko = '탐나불린(Tamnavulin)은 스코틀랜드 스페이사이드에 자리하고 있습니다. 1966년 리벳 계곡에 세워진 스페이사이드 증류소로, 1990년대 중반 장기간 가동을 멈췄다가 2007년 생산을 재개했습니다. 부드러운 과일과 바닐라를 중심으로 한 접근성 좋은 싱글 몰트를 주로 선보입니다. 현재는 Whyte & Mackay 소속으로 운영되고 있습니다.',
