  description_ko = '블레어 아솔(Blair Athol)은 1798년에 설립된 스코틀랜드 하이랜드의 위스키 증류소입니다. 피틀로크리 중심부에 자리한 오래된 하이랜드 증류소로 Bell’s 블렌드의 중요한 몰트 원액입니다. 견과류와 몰트, 건과일, 약간의 셰리 풍미가 어우러지는 비교적 풍부한 스타일을 보여줍니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
