  description_en = 'Ladyburn is a historic closed whisky distillery associated with Lowlands, Scotland, with a historical reference date of 1966. It is currently associated with William Grant & Sons. It is part of the Lowland tradition, generally associated with a lighter, floral and cereal-driven style, while retaining its own production character.',
  description_ko = '레이디번(Ladyburn)은 현재는 가동하지 않는 스코틀랜드 로우랜드의 역사적인 위스키 증류소입니다. William Grant & Sons가 Girvan 그레인 증류소 안에 설치했던 몰트 증류 시설로, 1966년부터 1975년까지만 짧게 운영됐습니다. 생산 기간이 매우 짧아 남아 있는 원액이 희귀하며 독립 병입과 고가의 장기 숙성 제품으로 주로 알려져 있습니다.',
  type = 'DISTILLERY'
WHERE id = 194;

