  description_ko = '킨클레이스(Kinclaith)은 현재는 가동하지 않는 스코틀랜드 로우랜드의 역사적인 위스키 증류소입니다. 글래스고 Strathclyde 그레인 증류소 부지 안에서 1957~1975년 운영된 몰트 증류 시설입니다. 생산 기간이 짧고 설비가 철거돼 현재는 ‘silent distillery’로 분류되며, 남은 병입은 매우 희귀합니다.',
