  description_ko = '벤 위비스(Ben Wyvis)은 1965년에 설립되어 현재는 가동하지 않는 스코틀랜드 하이랜드의 역사적인 위스키 증류소입니다. 1960년대 Invergordon 단지 안에 세워졌던 몰트 증류 시설로 1970년대 후반 폐쇄됐습니다. 운영 기간이 짧아 원액이 극히 희귀하며, 오늘날에는 주로 역사적 병입과 경매 시장에서 이름을 접합니다.',
