  description_en = 'Kilbeggan is a active whisky distillery associated with County Westmeath, Ireland, with a historical reference date of 1757. It is currently associated with Suntory Global Spirits. Its production sits within the modern Irish whiskey revival, using malt, pot still and/or grain whiskey techniques depending on the site.',
  description_ko = '킬베간(Kilbeggan)은 아일랜드 웨스트미스 (킬베간)에 자리하고 있습니다. 1757년 면허 기록을 바탕으로 세계에서 가장 오래된 면허 증류소 가운데 하나로 소개되는 아일랜드 생산자입니다. 여러 차례 중단을 겪었지만 2007년 현장에서 증류가 다시 시작됐으며, 작은 팟 스틸과 역사적인 설비를 활용해 전통적인 아일랜드 위스키의 분위기를 보여줍니다. 현재는 Suntory Global Spirits 소속으로 운영되고 있습니다.',
