  description_ko = '로 앤 코(Roe & Co)은 아일랜드 더블린에 자리하고 있습니다. Diageo가 더블린의 옛 Guinness 양조장 일대에 세운 현대적인 아이리시 위스키 증류소로 2019년 문을 열었습니다. 부드럽고 과일·바닐라 중심의 블렌디드 아이리시 위스키를 기반으로 하면서 자체 원액의 장기적인 역할도 확대하고 있습니다.',
