  description_ko = '엉클 니어리스트(Uncle Nearest)는 Nathan ‘Nearest’ Green의 역사와 테네시 위스키 전통을 기리기 위해 2017년 출범한 위스키 브랜드입니다. Nearest Green Distillery는 2019년 방문객에게 문을 열었으며, 테네시 위스키와 미국 위스키를 중심으로 생산 기반을 확대해 왔습니다. 2025년부터 회사는 법원 지정 관리인 아래 운영되고 있고 2026년에는 매각 절차가 진행 중이지만, 증류소와 방문 시설은 계속 운영되고 있습니다.',
