  description_ko = '캐슬 앤 키(Castle & Key)은 2018년에 설립된 미국 켄터키의 위스키 증류소입니다. E.H. Taylor가 세운 역사적 Old Taylor Distillery 부지를 복원해 다시 태어난 켄터키 증류소입니다. 성처럼 보이는 건물과 석회암 샘을 되살려 버번·라이·진 등을 생산하며, 장기간 방치된 유서 깊은 증류 시설을 현대적으로 복원한 사례로 유명합니다.',
