  description_en = 'Stitzel-Weller is a historic closed whisky distillery associated with Kentucky, United States, with a historical reference date of 1935. It is currently associated with Diageo. Its whiskey production is rooted in American grain recipes, new-oak maturation and the distillery’s own approach to fermentation, distillation and blending.',
  description_ko = '스티첼-웰러(Stitzel-Weller)은 현재는 가동하지 않는 미국 켄터키의 역사적인 위스키 증류소입니다. 1935년 더비 데이에 문을 연 루이빌의 전설적인 버번 증류소로, 과거 Old Fitzgerald와 W.L. Weller 등 여러 ‘wheated bourbon’ 계보와 연결됩니다. 1992년 실제 증류는 중단됐고 현재 부지는 Diageo의 방문·숙성 거점으로 활용되고 있어, 현역 생산 증류소와는 구분할 필요가 있습니다.',
