  description_ko = '앨버타 디스틸러스(Alberta Distillers)은 1946년에 설립된 캐나다 앨버타의 위스키 증류소입니다. 캘거리에 자리한 캐나다의 대표적인 라이 위스키 생산자 중 하나로, 높은 라이 비율의 원액 생산에 강점을 가지고 있습니다. Alberta Premium과 여러 북미 라이 위스키의 기반 원액으로 유명하며, 캐나다식 컬럼 증류와 장기 숙성의 특성을 잘 보여줍니다. 현재는 Suntory Global Spirits 소속으로 운영되고 있습니다.',
