  description_ko = '포티 크릭(Forty Creek)은 1992년에 설립된 캐나다 온타리오의 위스키 증류소입니다. 온타리오 그림즈비(Grimsby) 지역에서 John K. Hall이 발전시킨 캐나다 위스키 생산자입니다. 옥수수·호밀·보리를 각각 증류·숙성한 뒤 블렌딩하는 접근으로 유명하며, 과일과 향신료, 바닐라가 균형을 이루는 스타일을 지향합니다. 현재는 Campari Group 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 211;

