  description_en = 'Limeburners is a active whisky distillery associated with Western Australia, Australia, with a historical reference date of 2004. It is currently associated with Great Southern Distilling Company. It develops its house style through local raw materials, fermentation, distillation and cask maturation.',
  description_ko = '라임버너스(Limeburners)은 2004년에 설립된 호주 서오스트레일리아 (앨버니)의 위스키 증류소입니다. 서호주 Albany 지역의 Great Southern Distilling Company가 만드는 싱글 몰트 브랜드입니다. 해양성 기후와 지역 곡물, 다양한 와인·버번 캐스크를 활용하며, 호주 본토의 초기 크래프트 싱글 몰트 생산자 중 하나로 평가됩니다.',
