  description_ko = '헬리어스 로드(Hellyers Road)은 1999년에 설립된 호주 태즈메이니아의 위스키 증류소입니다. 태즈메이니아 북서부 Burnie 인근에서 시작한 싱글 몰트 증류소로, 낙농 협동조합 배경에서 발전한 독특한 역사를 가지고 있습니다. 비피트와 피티드 원액 모두 생산하며 과일·몰트·바닐라 중심의 깨끗한 스타일을 보여줍니다.',
