  description_ko = '베이커리 힐(Bakery Hill)은 1999년에 설립된 호주 멜버른의 위스키 증류소입니다. 멜버른에서 David Baker와 가족이 시작한 호주의 소규모 싱글 몰트 생산자입니다. 작은 배치의 전통 pot still 증류와 고품질 몰트에 집중하며, 클래식한 비피트 스타일뿐 아니라 피티드 제품도 선보여 호주 크래프트 위스키의 초기 성공 사례로 꼽힙니다.',
