  description_ko = '퀴뢰(Kyrö)은 2012년에 설립된 핀란드 이소키로의 위스키 증류소입니다. 핀란드 이소퀴뢰의 옛 유제품 공장을 개조해 시작한 라이 중심 증류소입니다. 핀란드산 100% 라이를 적극적으로 사용하며, 추운 북유럽 환경과 현지 곡물의 스파이시하고 빵 같은 풍미를 현대적인 진·위스키 스타일로 풀어냅니다.',
