  description_ko = '맥캘란(The Macallan)은 스코틀랜드 스페이사이드에 자리하고 있습니다. 1824년 스페이 강가 Easter Elchies 일대에서 시작한 세계적인 싱글 몰트 증류소입니다. 작은 증류기에서 얻는 진한 원액과 셰리로 시즈닝한 유럽·미국산 오크 캐스크 관리에 특히 큰 비중을 두며, 말린 과일·향신료·오크가 중심이 되는 풍부한 스타일로 유명합니다. 현재는 Edrington 소속으로 운영되고 있습니다.',
