  description_ko = '글렌피딕(Glenfiddich)은 스코틀랜드 스페이사이드에 자리하고 있습니다. William Grant가 가족과 함께 직접 증류소를 지어 1887년 크리스마스에 첫 원액을 받은 가족 경영 증류소입니다. Robbie Dhu 샘물을 사용하며 배와 사과 같은 신선한 과일, 몰트와 은은한 오크가 어우러지는 스타일로 싱글 몰트 대중화에 큰 역할을 했습니다.',
