  description_ko = '딩글(Dingle)은 아일랜드 케리 (딩글)에 자리하고 있습니다. 케리 반도 Dingle에 2012년 세워진 독립 크래프트 증류소로, 소규모 pot still 생산과 수작업을 강조합니다. 아이리시 싱글 몰트와 pot still 위스키에서 과일·몰트·향신료가 선명하며 진과 보드카도 함께 생산합니다.',
