  search_keywords = 'Waterford, 워터포드, Waterford Whisky',
  website = 'https://www.waterfordwhiskey.com/',
  description_en = 'Waterford is an Irish single malt project built around farm-by-farm barley provenance and an unusually detailed focus on terroir. After entering receivership in 2024, the distillery and brand were acquired in 2026 by Tennessee Distilling Group; the brand has returned to market while the production site goes through a restart and reinvestment phase.',
  description_ko = '워터포드(Waterford)은 아일랜드 워터포드에서 위스키를 만들어 온 생산자입니다. Mark Reynier가 2010년대 중반 옛 Guinness 양조장을 개조해 시작한 아이리시 싱글 몰트 프로젝트로, 농장별 보리와 테루아를 극단적으로 추적하는 방식으로 유명해졌습니다. 2024년 receivership 이후 2026년 Tennessee Distilling Group이 증류소와 브랜드를 인수했고, 공식 사이트는 다시 운영 중이며 생산 설비 재가동을 준비하는 전환기에 있습니다.',
  type = 'DISTILLERY'
WHERE id = 98;

