  description_ko = '슬레인(Slane)은 2017년에 설립된 아일랜드 미스 (슬레인)의 위스키 증류소입니다. Meath의 Slane Castle 부지에 세워진 현대 아이리시 위스키 증류소로 Brown-Forman과 Conyngham 가문이 함께 개발했습니다. 몰트·grain·pot still 원액 생산과 다양한 캐스크 숙성을 통해 부드러운 과일·바닐라·향신료 중심의 Slane 블렌드를 만듭니다.',
