  description_ko = '짐 빔(Jim Beam)은 미국 켄터키에 자리하고 있습니다. Beam 가문의 버번 역사를 1795년까지 거슬러 소개하는 켄터키 대표 생산자입니다. 현재 Clermont와 Boston 일대의 대규모 생산 시설을 통해 Jim Beam과 Knob Creek 등 여러 브랜드를 만들며, 옥수수의 단맛·바닐라·오크·땅콩 같은 고소함이 대표적입니다. 현재는 Suntory Global Spirits 소속으로 운영되고 있습니다.',
