  description_ko = '메이커스 마크(Maker''s Mark)은 1953년에 설립된 미국 켄터키의 위스키 증류소입니다. 1950년대 Bill Samuels Sr.가 켄터키 Loretto에서 시작한 버번 생산자로, 호밀 대신 붉은 겨울밀을 사용하는 wheated bourbon 레시피가 핵심입니다. 부드러운 캐러멜·바닐라·빵의 단맛과 둥근 질감, 손으로 찍는 붉은 왁스 봉인이 상징적입니다. 현재는 Suntory Global Spirits 소속으로 운영되고 있습니다.',
