  description_en = 'Buffalo Trace is a active whisky distillery associated with Kentucky, United States, with a historical reference date of 1773. It is currently associated with Sazerac. Its whiskey production is rooted in American grain recipes, new-oak maturation and the distillery’s own approach to fermentation, distillation and blending.',
  description_ko = '버팔로 트레이스(Buffalo Trace)은 1773년에 설립된 미국 켄터키의 위스키 증류소입니다. Frankfort의 Kentucky River 강변에 자리한 미국의 대표적인 역사 증류소로, 부지의 증류 역사를 18세기 후반까지 거슬러 설명합니다. 여러 mash bill과 숙성 실험을 통해 Buffalo Trace, Eagle Rare, Blanton’s, Weller 등 폭넓은 버번을 생산합니다. 현재는 Sazerac 소속으로 운영되고 있습니다.',
