  description_en = 'Woodford Reserve is a active whisky distillery associated with Kentucky, United States, with a historical reference date of 1812. It is currently associated with Brown-Forman. Its whiskey production is rooted in American grain recipes, new-oak maturation and the distillery’s own approach to fermentation, distillation and blending.',
  description_ko = '우드포드 리저브(Woodford Reserve)은 1812년에 설립된 미국 켄터키의 위스키 증류소입니다. Versailles 인근의 역사적 Labrot & Graham 부지에서 생산되는 Brown-Forman의 프리미엄 버번입니다. 전통적인 컬럼 증류 원액과 별도로 3기의 pot still을 활용하는 독특한 생산 환경을 갖추며, 과일·견과류·코코아·향신료가 복합적으로 나타나는 스타일을 목표로 합니다.',
