  website = 'https://www.fourrosesbourbon.com/',
  description_en = 'Four Roses is a historic Kentucky bourbon producer famous for combining two mash bills with five proprietary yeast strains to create ten distinct bourbon recipes. Ownership transferred from Kirin to Gallo in April 2026, with Gallo stating that the existing production team and traditions would remain in place.',
  description_ko = '포 로지스(Four Roses)은 1888년에 설립된 미국 켄터키의 위스키 증류소입니다. 10개의 서로 다른 버번 레시피(2개 mash bill × 5개 효모)를 조합하는 독특한 생산 방식으로 유명한 켄터키 증류소입니다. 2026년 4월 Kirin에서 Gallo로 소유권이 이전됐으며, 현 생산팀과 레시피 체계는 유지되고 있습니다.',
