  description_ko = '헤븐 힐(Heaven Hill)은 미국 켄터키에 자리하고 있습니다. 1935년 Shapira 가문이 설립한 미국 최대급 가족 소유 위스키 회사로, Bardstown의 역사와 Louisville Bernheim Distillery의 생산 기반을 함께 운영합니다. 여러 mash bill로 Evan Williams, Elijah Craig, Larceny, Rittenhouse, Bernheim 등 버번·라이·위트 위스키를 폭넓게 생산합니다.',
