  description_ko = '잭 다니엘스(Jack Daniel''s)은 1866년에 설립된 미국 테네시의 위스키 증류소입니다. 테네시 Lynchburg의 Cave Spring Hollow에 자리한 미국의 상징적인 위스키 증류소입니다. 증류액을 설탕단풍나무 숯층으로 천천히 통과시키는 Lincoln County Process와 철분이 적은 샘물, 새로 태운 미국산 오크통 숙성으로 부드러운 바닐라·바나나·카라멜 스타일을 만듭니다. 현재는 Brown-Forman 소속으로 운영되고 있습니다.',
