  description_ko = '조지 디켈(George Dickel)은 1870년에 설립된 미국 테네시의 위스키 증류소입니다. Tullahoma의 Cascade Hollow에 자리한 대표적인 테네시 위스키 생산자입니다. Lincoln County Process의 숯 여과를 사용하고 증류액을 낮은 온도로 식힌 뒤 여과하는 전통을 강조하며, 옥수수의 단맛·미네랄·바닐라·향신료가 어우러집니다. 현재는 Diageo 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 110;

