  description_ko = '믹터스(Michter''s)은 미국 켄터키에 자리하고 있습니다. Michter’s는 1753년 펜실베이니아 계보를 브랜드 유산으로 사용하지만 현재 생산 기반은 켄터키에 새로 구축된 현대 증류 시스템입니다. Shively 증류소와 Fort Nelson 방문 거점을 운영하며, 비교적 낮은 배럴 투입 도수와 열순환 숙성 등 세밀한 생산 관리로 버번·라이를 만듭니다. 현재는 Chatham Imports 계열 소속으로 운영되고 있습니다.',
