  description_ko = '휘슬피그(WhistlePig)은 미국 버몬트에 자리하고 있습니다. 2007년 버몬트의 라이 위스키 전문 브랜드로 시작해 초기에는 캐나다산 숙성 라이를 선별·블렌딩하는 방식으로 성장했습니다. 2015년 Shoreham 농장에 자체 증류소를 열고 현지 라이 재배부터 증류·숙성까지 확대해 ‘farm-to-glass’ 생산 비중을 꾸준히 높이고 있습니다.',
