  description_ko = '마르스 츠누키(Mars Tsunuki)은 일본 가고시마에 자리하고 있습니다. Hombo Shuzo의 발상지인 가고시마 Tsunuki에 2016년 세워진 두 번째 본격 위스키 증류소입니다. Shinshu보다 따뜻한 남부 기후에서 원액을 생산·숙성해 같은 Mars 계열 안에서도 다른 숙성 속도와 과일·향신료의 성격을 비교할 수 있습니다.',
