  description_en = 'Mackmyra was founded in 1999 and became the pioneering name of modern Swedish single malt, using Swedish barley, local peat and innovative maturation. The company entered bankruptcy in 2024 and its assets were acquired, but Swedish reporting in 2026 indicated that distillation remained suspended, so the brand''s ownership and the physical production status should be treated separately.',
  description_ko = '막미라(Mackmyra)은 스웨덴 옙플레에서 위스키를 만들어 온 생산자입니다. 1999년 설립되어 스웨덴산 보리·피트·오크와 중력식 증류 시설을 활용하며 북유럽 위스키의 선구자로 성장했습니다. 2024년 파산 후 자산이 새 소유 구조에 인수됐지만, 2026년 3월 기준 현지 보도에서는 증류 생산이 여전히 중단된 상태로 확인되어 ‘브랜드 존속’과 ‘실제 생산 가동’을 구분해 볼 필요가 있습니다.',
  type = 'DISTILLERY'
WHERE id = 144;

