  description_ko = '하이 코스트(High Coast)은 스웨덴 회가 쿠스텐에 자리하고 있습니다. 스웨덴 Höga Kusten 지역의 Ångermanälven 강변에 자리한 증류소로 2010년부터 생산을 시작했습니다. 계절 온도 차가 큰 숙성고를 활용해 캐스크 변화를 연구하며, 비피트·피티드 원액과 여러 오크 종류를 체계적으로 비교하는 실험적인 스타일이 특징입니다.',
