  description_ko = '설리번스 코브(Sullivans Cove)은 호주 태즈메이니아에 자리하고 있습니다. 1994년 태즈메이니아에서 시작한 싱글 몰트 브랜드로, 소규모 배치와 싱글 캐스크 병입을 통해 세계적인 명성을 얻었습니다. 버번·프렌치 오크 계열 캐스크와 태즈메이니아의 서늘한 기후를 활용해 진한 과일·몰트·오크의 균형을 보여줍니다.',
  type = 'DISTILLERY'
WHERE id = 147;

