  description_ko = '코츠월드(Cotswolds)은 잉글랜드 코츠월드에 자리하고 있습니다. 2014년 영국 Cotswolds에 세워진 증류소로 지역산 보리와 긴 발효, 높은 cut point를 사용해 과일 향이 풍부한 원액을 만드는 것을 강조합니다. STR 레드와인 캐스크 등 활발한 캐스크 활용으로 진한 과일·초콜릿·향신료가 나타나는 싱글 몰트가 대표적입니다.',
