  description_ko = '더 레이크스(The Lakes)은 잉글랜드 컴브리아에 자리하고 있습니다. Cumbria의 Lake District에 2014년 문을 연 잉글랜드 증류소로, 셰리 캐스크와 블렌딩·숙성 관리에 집중한 풍부한 스타일을 발전시켜 왔습니다. 2024년 영국 스파클링 와인 생산자 Nyetimber가 인수했으며, 이후에도 고급 싱글 몰트 중심 전략을 이어가고 있습니다.',
