  description_ko = '잉글리시 위스키 (세인트 조지스)(The English Whisky Co. (St. George''s))은 잉글랜드 노퍽에 자리하고 있습니다. 노퍽 Roudham에 2006년 세워진 St. George’s Distillery는 현대 잉글랜드 싱글 몰트 부흥의 가장 이른 사례 중 하나입니다. Nelstrop 가문이 운영하며 비피트와 피티드 원액을 모두 생산해 The English Whisky라는 이름으로 과일·몰트·연기 등 다양한 스타일을 선보입니다.',
