  website = 'https://www.jamessedgwickdistillery.co.za/',
  description_en = 'James Sedgwick Distillery is a active whisky distillery associated with 웰링턴, South Africa, with a historical reference date of 1886. It is currently associated with part of Heineken Beverages. It develops its house style through local raw materials, fermentation, distillation and cask maturation.',
  description_ko = '제임스 세지윅(James Sedgwick Distillery)은 1886년에 설립된 남아프리카공화국 웰링턴의 위스키 증류소입니다. 남아프리카공화국 Wellington에 자리한 역사적인 증류소로 Three Ships와 Bain’s Cape Mountain Whisky를 생산합니다. 따뜻한 기후와 현지 곡물을 활용하며, 몰트와 그레인 위스키를 모두 다룰 수 있는 생산 기반을 갖춘 아프리카 대표 위스키 생산자입니다. 현재는 Heineken Beverages 계열 소속으로 운영되고 있습니다.',
  type = 'DISTILLERY'
WHERE id = 157;

-- id=512 | Bodegas Aalto
UPDATE producer
SET
  founded_year = 1999,
  name_en = 'Bodegas Aalto',
  name_ko = '보데가스 아알토',
  search_keywords = 'Bodegas Aalto, 보데가스 아알토',
  website = 'https://www.aalto.es/',
  description_en = 'Bodegas Aalto is a wine producer from Spain established in 1999. Tempranillo, locally known as Tinto Fino, is shaped by high elevations and large temperature swings into concentrated yet structured reds. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '보데가스 아알토(Bodegas Aalto)는 1999년에 시작된 리베라 델 두에로의 와인 생산자입니다. 마리아노 가르시아와 하비에르 사카니니가 시작했으며, 리베라 델 두에로의 여러 마을에서 오래된 틴토 피노(템프라니요) 포도밭을 선별해 농축감과 세련된 질감을 함께 추구하는 것으로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 512;

-- id=513 | Numanthia
UPDATE producer
SET
  founded_year = 1998,
  name_en = 'Numanthia',
  name_ko = '누만시아',
  search_keywords = 'Numanthia, 누만시아',
  website = 'https://www.numanthia.com/',
  description_en = 'Numanthia is a wine producer from Spain established in 1998. It focuses on old-vine Tinta de Toro from the harsh Toro landscape and is part of LVMH Moët Hennessy. Native varieties and old vineyards are important assets, with the wines balancing fruit concentration and complexity from ageing. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '누만시아(Numanthia)는 1998년에 시작된 토로의 와인 생산자입니다. 토로의 강한 일조와 척박한 토양에서 자라는 틴타 데 토로, 특히 오래된 포도나무를 핵심 자산으로 삼으며 힘과 농축감, 장기 숙성력을 강조합니다. 현재는 LVMH의 Moët Hennessy 포트폴리오에 속합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 513;

-- id=514 | Clos Erasmus
UPDATE producer
SET
  founded_year = 1989,
  name_en = 'Clos Erasmus',
  name_ko = '클로스 에라스무스',
  search_keywords = 'Clos Erasmus, 클로스 에라스무스',
  website = 'https://closerasmus.com/',
  description_en = 'Clos Erasmus is a wine producer from Spain established in 1989. Garnacha and Cariñena grown on steep llicorella slate slopes produce concentrated wines with strong mineral character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '클로스 에라스무스(Clos Erasmus)는 1989년에 시작된 프리오라트의 와인 생산자입니다. 다프네 글로리안이 프리오라트 재건 움직임에 참여하며 성장한 소규모 생산자로, 가르나차 중심의 낮은 수확량과 리코렐라 점판암 토양에서 나오는 깊이와 미네랄감을 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 514;

-- id=515 | Codorníu
UPDATE producer
SET
  founded_year = 1551,
  name_en = 'Codorníu',
  name_ko = '코도르니우',
  search_keywords = 'Codorníu, Codorniu, 코도르니우',
  website = 'https://www.codorniu.com/',
  description_en = 'Codorníu is a wine producer from Spain whose documented estate, family or commercial history reaches back to 1551. Native varieties and old vineyards are important assets, with the wines balancing fruit concentration and complexity from ageing. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '코도르니우(Codorníu)는 공식·역사 자료에서 1551년까지 이어지는 뿌리를 확인할 수 있는 카탈루냐 (카바)의 와인 생산자입니다. 라벤토스 가문이 1872년 스페인 토착 품종을 이용해 전통 방식 스파클링 와인을 만들며 카바 역사에 큰 전환점을 만든 생산자입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 515;

-- id=516 | Freixenet
UPDATE producer
SET
  founded_year = 1861,
  name_en = 'Freixenet',
  name_ko = '프레이셰넷',
  search_keywords = 'Freixenet, 프레이셰넷',
  website = 'https://freixenet.com/',
  description_en = 'Freixenet is a wine producer from Spain whose documented estate, family or commercial history reaches back to 1861. It helped turn Cava into a global sparkling-wine category; since March 2026 Freixenet S.A. has been wholly owned by Henkell Freixenet. Native varieties and old vineyards are important assets, with the wines balancing fruit concentration and complexity from ageing. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '프레이셰넷(Freixenet)은 공식·역사 자료에서 1861년까지 이어지는 뿌리를 확인할 수 있는 카탈루냐 (카바)의 와인 생산자입니다. 카바를 세계적인 대중 스파클링 와인으로 확산시킨 대표 브랜드이며, 2026년 3월부터 Henkell Freixenet가 지분 100%를 보유하고 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 516;

-- id=517 | Quinta do Vale Meão
UPDATE producer
SET
  founded_year = 1999,
  name_en = 'Quinta do Vale Meão',
  name_ko = '키타 두 발 메앙',
  search_keywords = 'Quinta do Vale Meão, Quinta do Vale Meao, 키타 두 발 메앙',
  website = 'https://quintadovalemeao.pt/',
  description_en = 'Quinta do Vale Meão is a wine producer from Portugal established in 1999. Native varieties such as Touriga Nacional and Touriga Franca grow on steep schist slopes and are used for both Port and structured dry wines. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '키타 두 발 메앙(Quinta do Vale Meão)은 1999년에 시작된 도루의 와인 생산자입니다. 도루 최상류의 역사적인 단일 에스테이트로, 과거 Barca Velha의 핵심 포도 공급지였으며 오늘날에는 투리가 나시오날을 비롯한 포르투갈 토착 품종으로 구조감 있는 드라이 레드와인을 만듭니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 517;

-- id=518 | Esporão
