SET
  founded_year = 1973,
  name_en = 'Esporão',
  name_ko = '에스포랑',
  search_keywords = 'Esporão, Esporao, 에스포랑',
  website = 'https://www.esporao.com/',
  description_en = 'Esporão is a wine producer from Portugal established in 1973. Portuguese native varieties are combined with the country’s blending traditions and modern vineyard management. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '에스포랑(Esporão)은 1973년에 시작된 알렌테주의 와인 생산자입니다. 알렌테주의 Herdade do Esporão를 중심으로 토착 품종과 국제 품종을 폭넓게 다루며, 유기농 전환과 토양 생태계 보전에 적극적인 대형 에스테이트입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 518;

