  website = 'https://www.luispato.com/',
  description_en = 'Luís Pato is a wine producer from Portugal established in 1980. Portuguese native varieties are combined with the country’s blending traditions and modern vineyard management. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '루이스 파투(Luís Pato)는 1980년에 시작된 바이라다의 와인 생산자입니다. 바이라다의 바가(Baga) 품종을 현대적으로 재해석한 대표 생산자로, 강한 탄닌과 높은 산도를 가진 바가의 장기 숙성 잠재력을 알리는 데 큰 역할을 했습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
