  website = 'https://www.weingutprager.at/',
  description_en = 'Weingut Prager is a wine producer from Austria whose documented estate, family or commercial history reaches back to 1715. Grüner Veltliner and Riesling from steep Danube terraces combine ripe fruit with acidity, herbal detail and stony minerality. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '프라거(Weingut Prager)는 공식·역사 자료에서 1715년까지 이어지는 뿌리를 확인할 수 있는 바하우의 와인 생산자입니다. Grüner Veltliner와 Riesling이 중심이며, 도나우 강변의 가파른 계단식 포도밭에서 높은 산도와 잘 익은 과실, 돌·허브 계열의 미네랄을 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 527;

-- id=528 | Nikolaihof
