  search_keywords = 'Nikolaihof, 니콜라이호프',
  website = 'https://www.nikolaihof.at/',
  description_en = 'Nikolaihof is a wine producer from Austria whose documented estate, family or commercial history reaches back to 1894. Grüner Veltliner and Riesling from steep Danube terraces combine ripe fruit with acidity, herbal detail and stony minerality. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '니콜라이호프(Nikolaihof)는 공식·역사 자료에서 1894년까지 이어지는 뿌리를 확인할 수 있는 바하우의 와인 생산자입니다. Grüner Veltliner와 Riesling이 중심이며, 도나우 강변의 가파른 계단식 포도밭에서 높은 산도와 잘 익은 과실, 돌·허브 계열의 미네랄을 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
