-- id=529 | Shafer Vineyards
UPDATE producer
SET
  founded_year = 1972,
  name_en = 'Shafer Vineyards',
  name_ko = '샤퍼 빈야드',
  search_keywords = 'Shafer Vineyards, 샤퍼 빈야드',
  website = 'https://www.shafervineyards.com/',
  description_en = 'Shafer Vineyards is a wine producer from the United States established in 1972. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '샤퍼 빈야드(Shafer Vineyards)는 1972년에 시작된 나파 밸리 (스택스 립)의 와인 생산자입니다. Stags Leap District의 Hillside Select Cabernet Sauvignon으로 유명하며, 산지 포도밭의 농축감과 잘 익은 탄닌을 결합한 나파 스타일을 대표합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 529;

-- id=530 | Joseph Phelps Vineyards
UPDATE producer
SET
  founded_year = 1973,
  name_en = 'Joseph Phelps Vineyards',
  name_ko = '조셉 펠프스',
  search_keywords = 'Joseph Phelps Vineyards, 조셉 펠프스',
  website = 'https://www.josephphelps.com/',
  description_en = 'Joseph Phelps Vineyards is a wine producer from the United States established in 1973. It is especially known for Insignia, a benchmark Napa Bordeaux-style blend, and is now part of LVMH Moët Hennessy. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '조셉 펠프스(Joseph Phelps Vineyards)는 1973년에 시작된 나파 밸리의 와인 생산자입니다. 보르도 품종 블렌드 Insignia로 널리 알려진 나파 생산자이며, 현재 LVMH Moët Hennessy가 소유해 나파와 소노마 코스트의 포도밭을 함께 운영합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 530;

