  description_ko = '샤플렛(Chappellet)은 1967년에 시작된 나파 밸리의 와인 생산자입니다. Cabernet Sauvignon을 중심으로 Chardonnay, Merlot, Sauvignon Blanc 등도 생산하며, 따뜻한 낮과 서늘한 밤의 일교차를 이용해 풍부한 과실과 균형 잡힌 산도를 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 538;

-- id=539 | Bond Estates
UPDATE producer
SET
  founded_year = 1999,
  name_en = 'Bond Estates',
  name_ko = '본드',
  search_keywords = 'Bond Estates, 본드',
  website = 'https://www.bond.wine/',
  description_en = 'Bond Estates is a wine producer from the United States established in 1999. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '본드(Bond Estates)는 1999년에 시작된 나파 밸리의 와인 생산자입니다. Cabernet Sauvignon을 중심으로 Chardonnay, Merlot, Sauvignon Blanc 등도 생산하며, 따뜻한 낮과 서늘한 밤의 일교차를 이용해 풍부한 과실과 균형 잡힌 산도를 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
