WHERE id = 539;

-- id=540 | Scarecrow
UPDATE producer
SET
  founded_year = 2003,
  name_en = 'Scarecrow',
  name_ko = '스케어크로',
  search_keywords = 'Scarecrow, 스케어크로',
  website = 'https://www.scarecrowwine.com/',
  description_en = 'Scarecrow is a wine producer from the United States established in 2003. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '스케어크로(Scarecrow)는 2003년에 시작된 나파 밸리 (러더퍼드)의 와인 생산자입니다. 러더퍼드의 오래된 J.J. Cohn Estate 포도밭에서 생산되는 카베르네 소비뇽을 중심으로 하며, 극히 제한된 생산량과 오래된 포도나무로 컬트 와인 지위를 얻었습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 540;

-- id=541 | Marcassin
UPDATE producer
SET
  founded_year = 1990,
  name_en = 'Marcassin',
  name_ko = '마카신',
  search_keywords = 'Marcassin, 마카신',
  website = '',
  description_en = 'Marcassin is a wine producer from the United States established in 1990. The region ranges from Pinot Noir and Chardonnay to Cabernet Sauvignon, with strong differences between sites created by Pacific cooling and complex soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '마카신(Marcassin)은 1990년에 시작된 소노마 (소노마 코스트)의 와인 생산자입니다. Pinot Noir와 Chardonnay부터 Cabernet Sauvignon까지 다양한 품종을 재배하며, 태평양의 냉각 효과와 복잡한 토양에 따라 세부 산지별 스타일 차이가 큽니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 541;

