  description_ko = '타블라스 크릭(Tablas Creek)은 1989년에 시작된 캘리포니아 (파소 로블레스)의 와인 생산자입니다. 프랑스 Château de Beaucastel의 Perrin 가문과 Haas 가문이 함께 세운 파소 로블레스 생산자로, 론 품종 묘목을 직접 도입하고 유기농·재생 농업을 일찍부터 추진했습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
