  website = 'https://www.duckhorn.com/',
  description_en = 'Duckhorn Vineyards is a wine producer from the United States established in 1976. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '덕혼(Duckhorn Vineyards)은 1976년에 시작된 나파 밸리 (세인트헬레나)의 와인 생산자입니다. 1976년 Dan과 Margaret Duckhorn이 설립했으며, Napa Valley에서 Merlot의 고급화를 이끈 대표 생산자입니다. Merlot 외에도 Cabernet Sauvignon, Sauvignon Blanc, Chardonnay를 생산하며 2026년에는 St. Helena 방문 시설을 리노베이션 중이지만 와인 생산과 브랜드 운영은 계속되고 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
