  description_en = 'Meiomi is a California wine brand created in 2006, built around multi-region coastal sourcing rather than one estate vineyard. Varieties are matched to local climate and vineyard conditions, with an emphasis on balancing ripe fruit, acidity and oak. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
