  search_keywords = 'Josh Cellars, 조시 셀러스',
  website = 'https://www.joshcellars.com/',
  description_en = 'Josh Cellars is a wine producer from the United States established in 2007. Varieties are matched to local climate and vineyard conditions, with an emphasis on balancing ripe fruit, acidity and oak. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '조시 셀러스(Josh Cellars)는 2007년에 시작된 캘리포니아의 와인 생산자입니다. 현지 기후와 포도밭 조건에 맞는 품종을 중심으로 완숙한 과실과 산도, 오크 숙성의 균형을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 552;

