  search_keywords = 'Domaine Serene, 도멘 세렌, Serene',
  website = 'https://www.domaineserene.com/',
  description_en = 'Domaine Serene is a wine producer from the United States established in 1989. Pinot Noir and Chardonnay are central, particularly in the Willamette Valley, where a cool climate supports aromatic detail, acidity and site expression. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '도멘 세렌(Domaine Serene)은 1989년에 시작된 오리건의 와인 생산자입니다. Willamette Valley를 중심으로 Pinot Noir와 Chardonnay가 핵심이며, 서늘한 기후가 만드는 선명한 산도와 향기, 토양별 세밀한 차이를 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 553;

