  description_en = 'Two Hands is a wine producer from Australia established in 1999. Old-vine Shiraz and Grenache are major assets, producing ripe, spicy and full-bodied wines in the warm Barossa climate. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
