  website = '',
  description_en = 'Wendouree is a wine producer from Australia whose documented estate, family or commercial history reaches back to 1895. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '웬도우리(Wendouree)는 공식·역사 자료에서 1895년까지 이어지는 뿌리를 확인할 수 있는 클레어 밸리의 와인 생산자입니다. 지역의 기후와 오래된 포도나무를 활용해 풍부한 과실을 만들면서도 산도와 토양의 개성을 유지하는 스타일을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 562;

-- id=563 | Vasse Felix
UPDATE producer
SET
  founded_year = 1967,
  name_en = 'Vasse Felix',
  name_ko = '바스 펠릭스',
  search_keywords = 'Vasse Felix, 바스 펠릭스',
  website = 'https://www.vassefelix.com.au/',
  description_en = 'Vasse Felix is a wine producer from Australia established in 1967. Cabernet Sauvignon and Chardonnay dominate, with an Indian Ocean climate helping preserve acidity while achieving full flavour ripeness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '바스 펠릭스(Vasse Felix)는 1967년에 시작된 마가렛 리버의 와인 생산자입니다. 1967년 설립된 마가렛 리버 최초의 와이너리로 알려져 있으며, Cabernet Sauvignon과 Chardonnay를 중심으로 해양성 기후의 균형 잡힌 스타일을 보여줍니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 563;

-- id=564 | Moss Wood
UPDATE producer
SET
  founded_year = 1969,
  name_en = 'Moss Wood',
  name_ko = '모스 우드',
  search_keywords = 'Moss Wood, 모스 우드',
  website = 'https://www.mosswood.com.au/',
  description_en = 'Moss Wood is a wine producer from Australia established in 1969. Cabernet Sauvignon and Chardonnay dominate, with an Indian Ocean climate helping preserve acidity while achieving full flavour ripeness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '모스 우드(Moss Wood)는 1969년에 시작된 마가렛 리버의 와인 생산자입니다. Cabernet Sauvignon과 Chardonnay가 중심이며, 인도양의 해양성 기후가 과실의 성숙도와 산도를 균형 있게 유지해 줍니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 564;

-- id=565 | Tyrrell's
UPDATE producer
SET
  founded_year = 1858,
  name_en = 'Tyrrell''s',
  name_ko = '티렐스',
  search_keywords = 'Tyrrell''s, 티렐스',
  website = 'https://tyrrells.com.au/',
  description_en = 'Tyrrell''s is a wine producer from Australia whose documented estate, family or commercial history reaches back to 1858. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '티렐스(Tyrrell''s)는 공식·역사 자료에서 1858년까지 이어지는 뿌리를 확인할 수 있는 헌터 밸리의 와인 생산자입니다. 헌터 밸리의 오래된 가족 생산자로, 낮은 알코올과 높은 산도를 지닌 Hunter Semillon 및 오래된 Shiraz 포도밭을 보존하는 것으로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 565;

