  search_keywords = 'Wolf Blass, 울프 블라스',
  website = 'https://www.wolfblass.com/',
  description_en = 'Wolf Blass is a wine producer from Australia established in 1966. Old-vine Shiraz and Grenache are major assets, producing ripe, spicy and full-bodied wines in the warm Barossa climate. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
