  website = 'https://19crimes.com/',
  description_en = '19 Crimes is an Australian wine brand launched in 2012 and operated by Treasury Wine Estates rather than a single-estate winery. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '19 크라임스(19 Crimes)는 2012년에 시작된 호주 와인 브랜드로, 물리적인 단일 와이너리보다 Treasury Wine Estates가 운영하는 브랜드 프로젝트에 가깝습니다. 라벨에는 19세기 영국에서 호주로 유배된 죄수들의 이야기를 담아 강한 브랜드 정체성을 만들었으며, Shiraz와 Red Blend 등 풍부한 과실과 부드러운 질감을 강조한 접근성 높은 스타일이 중심입니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
