  search_keywords = 'Craggy Range, 크래기 레인지',
  website = 'https://www.craggyrange.com/',
  description_en = 'Craggy Range is a wine producer from New Zealand established in 1998. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
