  search_keywords = 'Rippon, 리폰',
  website = 'https://www.rippon.co.nz/',
  description_en = 'Rippon is a wine producer from New Zealand established in 1982. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '리폰(Rippon)은 1982년에 시작된 센트럴 오타고의 와인 생산자입니다. 서늘한 해양성 기후를 활용해 선명한 향과 높은 산도를 살리고, 지역별 포도밭 차이를 세밀하게 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
