  description_en = 'Kumeu River is a wine producer from New Zealand established in 1944. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '쿠뮤 리버(Kumeu River)는 1944년에 시작된 오클랜드의 와인 생산자입니다. 브라코비치 가문이 운영하며, 오클랜드의 Chardonnay를 부르고뉴식 배럴 발효와 세심한 리 숙성으로 양조해 뉴질랜드 고급 Chardonnay의 기준을 높인 생산자입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
