  search_keywords = 'Greywacke, 그레이와키',
  website = 'https://greywacke.com/',
  description_en = 'Greywacke is a wine producer from New Zealand established in 2009. Sauvignon Blanc leads the region with vivid citrus, tropical fruit, herbs and acidity, alongside growing Pinot Noir and Chardonnay production. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
