  website = 'https://dogpoint.co.nz/',
  description_en = 'Dog Point is a wine producer from New Zealand established in 2002. Sauvignon Blanc leads the region with vivid citrus, tropical fruit, herbs and acidity, alongside growing Pinot Noir and Chardonnay production. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '도그 포인트(Dog Point)는 2002년에 시작된 말버러의 와인 생산자입니다. Cloudy Bay 출신 이반 서덜랜드와 제임스 힐리가 세운 말버러 생산자로, 낮은 수확량과 긴 숙성, 야생 효모 발효를 활용한 진지한 Sauvignon Blanc과 Pinot Noir로 알려져 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 574;

