  description_ko = '브랜콧 이스테이트(Brancott Estate)는 1934년에 시작된 말버러의 와인 생산자입니다. Sauvignon Blanc을 중심으로 강한 향과 높은 산도, 시트러스·열대과일·허브의 선명한 풍미를 보여주며 Pinot Noir와 Chardonnay도 생산합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
