  search_keywords = 'Casa Lapostolle, 카사 라포스톨',
  website = 'https://www.lapostollewines.com/',
  description_en = 'Casa Lapostolle is a wine producer from Chile established in 1994. Vineyards influenced by the Andes and Pacific combine ripe fruit with freshness and acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '카사 라포스톨(Casa Lapostolle)은 1994년에 시작된 콜차과 (아팔타)의 와인 생산자입니다. 프랑스 Marnier-Lapostolle 가문이 칠레에 설립했으며, 아팔타의 오래된 Carmenère와 보르도 품종을 활용한 Clos Apalta로 국제적인 명성을 얻었습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 577;

