  description_en = 'Don Melchor is Concha y Toro’s flagship Cabernet Sauvignon project, first released from the 1987 vintage and centered on the Puente Alto vineyard. Cabernet Sauvignon is central to classic Chilean Bordeaux-style wines, with Andean gravel soils and diurnal shifts providing structure and freshness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '돈 멜초르(Don Melchor)는 1987년에 첫 빈티지를 선보인 Concha y Toro의 최고급 Cabernet Sauvignon 프로젝트로, 푸엔테 알토의 단일 생산 기반을 독립적인 와인 정체성으로 발전시켜 왔습니다. Puente Alto의 자갈·충적토 포도밭을 세부 구획으로 나누어 각각 양조한 뒤 최종 블렌딩하며, Cabernet Sauvignon을 중심으로 안데스 산기슭의 구조와 신선함을 표현합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
