  name_en = 'Sadie Family Wines',
  name_ko = '사디 패밀리',
  search_keywords = 'Sadie Family Wines, 사디 패밀리',
  website = 'https://www.thesadiefamily.com/',
  description_en = 'Sadie Family Wines is a wine producer from South Africa established in 1999. South Africa’s old vines and diverse soils are used to balance ripeness, freshness and savoury spice. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '사디 패밀리(Sadie Family Wines)는 1999년에 시작된 스와틀란트의 와인 생산자입니다. 에벤 사디가 Swartland의 오래된 Chenin Blanc, Cinsault 등 역사적 포도밭을 발굴해 지역과 품종의 개성을 최소 개입으로 표현하는 프로젝트로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 586;

-- id=587 | Mullineux
UPDATE producer
SET
  founded_year = 2007,
  name_en = 'Mullineux',
  name_ko = '멀리뉴',
  search_keywords = 'Mullineux, 멀리뉴',
  website = 'https://mlfwines.com/',
  description_en = 'Mullineux is a wine producer from South Africa established in 2007. South Africa’s old vines and diverse soils are used to balance ripeness, freshness and savoury spice. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '멀리뉴(Mullineux)는 2007년에 시작된 스와틀란트의 와인 생산자입니다. Swartland의 화강암·편암·철질 토양을 구분해 Syrah와 Chenin Blanc을 양조하며, 토양 차이를 명확하게 드러내는 세밀한 큐베 구성으로 잘 알려져 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 587;

-- id=588 | Rust en Vrede
UPDATE producer
SET
  founded_year = 1694,
  name_en = 'Rust en Vrede',
  name_ko = '러스트 엔 프레데',
  search_keywords = 'Rust en Vrede, 러스트 엔 프레데',
  website = 'https://rustenvrede.com/',
  description_en = 'Rust en Vrede is a wine producer from South Africa whose documented estate, family or commercial history reaches back to 1694. Cabernet Sauvignon, Pinotage and Chenin Blanc are shaped by mountainous terrain and maritime influences that create varied mesoclimates. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '러스트 엔 프레데(Rust en Vrede)는 공식·역사 자료에서 1694년까지 이어지는 뿌리를 확인할 수 있는 스텔렌보스의 와인 생산자입니다. Cabernet Sauvignon, Pinotage, Chenin Blanc 등을 중심으로 산악 지형과 해양성 영향이 만드는 다양한 미세 기후를 활용합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 588;

-- id=589 | Alpha Estate
UPDATE producer
SET
  founded_year = 1997,
  name_en = 'Alpha Estate',
  name_ko = '알파 이스테이트',
  search_keywords = 'Alpha Estate, 알파 이스테이트',
  website = 'https://alpha-estate.com/',
  description_en = 'Alpha Estate is a wine producer from Greece established in 1997. Native Greek varieties and distinctive island or mountain terroirs are used to preserve acidity, herbs and mineral character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '알파 이스테이트(Alpha Estate)는 1997년에 시작된 아민데오의 와인 생산자입니다. 그리스 토착 품종과 독특한 섬·산악 테루아를 중심으로 높은 산도와 허브·미네랄 풍미를 살리는 스타일을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 589;

