  website = 'https://www.gaiawines.gr/',
  description_en = 'Gaia Wines is a wine producer from Greece established in 1994. Assyrtiko grown in volcanic ash and pumice, often in low basket-trained vines, produces intense acidity and a saline mineral profile. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '가이아 와인스(Gaia Wines)는 1994년에 시작된 산토리니 / 네메아의 와인 생산자입니다. Assyrtiko를 중심으로 화산재와 부석 토양, 강한 바람에 적응한 낮은 바구니형 포도나무가 매우 높은 산도와 짭짤한 미네랄을 만들어 냅니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
