  description_en = 'Château Pavie is a wine producer from France established in 1998. The Saint-Émilion estate is centered on limestone plateau and slope parcels; the Perse family has managed and extensively redeveloped it since 1998. Cabernet Sauvignon and Merlot are central to the region, with blending used to express the balance between site, soil and vintage. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
