  website = '',
  description_en = 'Château Trotanoy is a wine producer from France whose documented estate, family or commercial history reaches back to 1750. Cabernet Sauvignon and Merlot are central to the region, with blending used to express the balance between site, soil and vintage. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '샤토 트로타누아(Château Trotanoy)는 공식·역사 자료에서 1750년까지 이어지는 뿌리를 확인할 수 있는 보르도의 와인 생산자입니다. Cabernet Sauvignon과 Merlot을 중심으로 한 보르도 품종을 재배하며, 자갈·점토·석회질 등 포도밭의 토양 차이와 빈티지 특성을 블렌딩으로 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 443;

