  description_en = 'Château Canon is a wine producer from France whose documented estate, family or commercial history reaches back to 1760. Cabernet Sauvignon and Merlot are central to the region, with blending used to express the balance between site, soil and vintage. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '샤토 카농(Château Canon)은 공식·역사 자료에서 1760년까지 이어지는 뿌리를 확인할 수 있는 보르도의 와인 생산자입니다. 생테밀리옹 석회암 고원에 자리한 Premier Grand Cru Classé B로 알려져 있으며, Chanel 소유 아래 Merlot 중심의 정교하고 섬세한 스타일을 발전시켰습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
