  description_en = 'Domaine Georges Roumier is a wine producer from France established in 1924. Pinot Noir and Chardonnay dominate, with a strong focus on expressing the differences between individual vineyard parcels and soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
