  description_ko = '도멘 실뱅 카티아르(Domaine Sylvain Cathiard)는 1969년에 시작된 부르고뉴의 와인 생산자입니다. Pinot Noir와 Chardonnay가 중심이며, 포도밭의 작은 구획과 토양 차이를 세밀하게 반영하는 것이 생산 철학의 핵심입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 454;

