  website = 'https://www.champagnejacquesson.com/',
  description_en = 'Jacquesson is a wine producer from France whose documented estate, family or commercial history reaches back to 1798. The Dizy house is known for the numbered Cuvée 700 series and site-specific Champagnes; the Pinault family acquired it in 2022. Chardonnay, Pinot Noir and Meunier are blended before traditional-method secondary fermentation and extended lees ageing build texture and complexity. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '자크송(Jacquesson)은 공식·역사 자료에서 1798년까지 이어지는 뿌리를 확인할 수 있는 샴페인의 와인 생산자입니다. Dizy를 기반으로 빈티지 성격을 반영한 번호형 Cuvée 700 시리즈와 단일 포도밭 샴페인을 만드는 생산자로, 2022년 Pinault 가문이 인수했습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
