  description_en = 'Gosset is a wine producer from France whose documented estate, family or commercial history reaches back to 1584. Chardonnay, Pinot Noir and Meunier are blended before traditional-method secondary fermentation and extended lees ageing build texture and complexity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
