  website = '',
  description_en = 'Jacques Selosse is a wine producer from France established in 1949. Chardonnay, Pinot Noir and Meunier are blended before traditional-method secondary fermentation and extended lees ageing build texture and complexity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
