  description_ko = '샤토 데스클랑 (위스퍼링 엔젤)(Château d''Esclans)은 2006년에 시작된 프로방스의 와인 생산자입니다. 사샤 리신이 2006년 인수한 이후 Provence rosé의 고급화를 목표로 발전했으며, Whispering Angel부터 오크 발효 Garrus까지 폭넓은 로제 스타일을 선보입니다. 현재 LVMH Moët Hennessy 소속입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
