  description_ko = '로베르토 보에르치오(Roberto Voerzio)는 1986년에 시작된 피에몬테의 와인 생산자입니다. Nebbiolo를 중심으로 Barolo와 Barbaresco의 장기 숙성형 와인을 만들며, Barbera와 Dolcetto 등 지역 품종도 함께 다룹니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
