  description_ko = '이솔레 에 올레나(Isole e Olena)는 1956년에 시작된 토스카나의 와인 생산자입니다. Chianti Classico의 산지 Sangiovese를 중심으로 전통과 현대성을 결합해 왔으며, Cepparello를 통해 100% Sangiovese의 고급화에 큰 영향을 준 생산자입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 488;

