  description_ko = '솔데라 (카제 바세)(Soldera (Case Basse))는 1972년에 시작된 토스카나의 와인 생산자입니다. Montalcino의 Case Basse 포도밭에서 Sangiovese만으로 매우 긴 숙성과 엄격한 선별을 거친 와인을 만들며, Brunello 규정보다 자체 철학을 우선하는 독립적 스타일로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
