  description_ko = '예르만(Jermann)은 공식·역사 자료에서 1881년까지 이어지는 뿌리를 확인할 수 있는 프리울리의 와인 생산자입니다. 지역의 토착 품종을 중심으로 전통적인 양조 방식과 현대적인 정밀함을 결합해 테루아의 차이를 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 500;

-- id=501 | Livio Felluga
UPDATE producer
SET
  founded_year = 1956,
  name_en = 'Livio Felluga',
  name_ko = '리비오 펠루가',
  search_keywords = 'Livio Felluga, 리비오 펠루가',
  website = 'https://www.liviofelluga.it/',
  description_en = 'Livio Felluga is a wine producer from Italy established in 1956. Local varieties are central, with traditional methods and modern precision combined to express regional terroir. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '리비오 펠루가(Livio Felluga)는 1956년에 시작된 프리울리의 와인 생산자입니다. 지역의 토착 품종을 중심으로 전통적인 양조 방식과 현대적인 정밀함을 결합해 테루아의 차이를 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 501;

-- id=502 | Tommasi
UPDATE producer
SET
  founded_year = 1902,
  name_en = 'Tommasi',
  name_ko = '톰마시',
  search_keywords = 'Tommasi, 톰마시',
  website = 'https://www.tommasi.com/',
  description_en = 'Tommasi is a wine producer from Italy established in 1902. The region spans Valpolicella and Amarone based on Corvina as well as white wines, with appassimento and extended ageing playing important roles. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '톰마시(Tommasi)는 1902년에 시작된 베네토의 와인 생산자입니다. Corvina 계열의 Valpolicella·Amarone부터 지역 화이트 와인까지 다양한 스타일을 다루며, 건조 포도와 장기 숙성 같은 전통 기법이 중요한 역할을 합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 502;

