  description_en = 'Bertani is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1857. The region spans Valpolicella and Amarone based on Corvina as well as white wines, with appassimento and extended ageing playing important roles. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '베르타니(Bertani)는 공식·역사 자료에서 1857년까지 이어지는 뿌리를 확인할 수 있는 베네토의 와인 생산자입니다. Corvina 계열의 Valpolicella·Amarone부터 지역 화이트 와인까지 다양한 스타일을 다루며, 건조 포도와 장기 숙성 같은 전통 기법이 중요한 역할을 합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
