  description_en = 'Ruffino is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1877. Sangiovese remains central, while many estates also use Cabernet Sauvignon and Merlot for modern Tuscan blends and single-variety wines. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '루피노(Ruffino)는 공식·역사 자료에서 1877년까지 이어지는 뿌리를 확인할 수 있는 토스카나의 와인 생산자입니다. Sangiovese를 중심으로 전통적인 토스카나 스타일을 만들거나 Cabernet Sauvignon, Merlot 같은 국제 품종을 활용해 현대적 블렌드를 생산합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
