  search_keywords = 'Kindzmarauli Marani, 킨즈마라울리 마라니',
  website = '',
  description_en = 'Kindzmarauli Marani is a wine producer from Georgia established in 2003. Native Georgian grapes such as Saperavi and Rkatsiteli are made with both traditional qvevri methods and modern cellar techniques. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '킨즈마라울리 마라니(Kindzmarauli Marani)는 2003년에 시작된 카헤티의 와인 생산자입니다. Saperavi와 Rkatsiteli 등 조지아 토착 품종을 사용하며, 전통적인 qvevri 발효와 현대식 양조를 병행해 다양한 스타일을 만듭니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 398;

