  description_en = 'Finca Bacara is a wine producer from Spain established in 2003. Native varieties and old vineyards are important assets, with the wines balancing fruit concentration and complexity from ageing. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '핀카 바카라(Finca Bacara)는 2003년에 시작된 후미야의 와인 생산자입니다. 지역의 토착 품종과 오래된 포도밭을 중요한 자산으로 삼고, 과실의 농도와 숙성에서 나오는 복합성을 함께 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 401;

