  website = 'https://dryriver.co.nz/',
  description_en = 'Dry River is a wine producer from New Zealand established in 1979. A pioneering Martinborough estate known for structured, age-worthy Pinot Noir and aromatic whites; in 2026 it returned to New Zealand ownership under Charlie Zheng. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '드라이 리버(Dry River)는 1979년에 시작된 마틴버러의 와인 생산자입니다. Martinborough의 초기 고급 와인 역사를 만든 생산자 가운데 하나로, Pinot Noir와 Riesling·Gewürztraminer 등에서 낮은 수확량과 장기 숙성형 스타일을 추구합니다. 2026년에는 Charlie Zheng이 인수하며 다시 뉴질랜드 소유가 되었습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
