  description_en = 'Pieropan is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1880. The region spans Valpolicella and Amarone based on Corvina as well as white wines, with appassimento and extended ageing playing important roles. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '피에로판(Pieropan)은 공식·역사 자료에서 1880년까지 이어지는 뿌리를 확인할 수 있는 베네토 (소아베)의 와인 생산자입니다. Corvina 계열의 Valpolicella·Amarone부터 지역 화이트 와인까지 다양한 스타일을 다루며, 건조 포도와 장기 숙성 같은 전통 기법이 중요한 역할을 합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 410;

-- id=411 | Benanti
UPDATE producer
SET
  founded_year = 1988,
  name_en = 'Benanti',
  name_ko = '베난티',
  search_keywords = 'Benanti, 베난티',
  website = 'https://www.benanti.it/',
  description_en = 'Benanti is a wine producer from Italy established in 1988. Native grapes such as Nero d’Avola, Nerello Mascalese and Carricante reflect both Mediterranean warmth and Sicily’s diverse volcanic and limestone soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '베난티(Benanti)는 1988년에 시작된 시칠리아 (에트나)의 와인 생산자입니다. Nero d’Avola, Nerello Mascalese, Carricante 등 토착 품종을 중심으로 지중해의 따뜻함과 화산·석회질 토양의 개성을 함께 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 411;

-- id=412 | Elio Altare
UPDATE producer
SET
  founded_year = 1948,
  name_en = 'Elio Altare',
  name_ko = '엘리오 알타레',
  search_keywords = 'Elio Altare, 엘리오 알타레',
  website = 'https://www.elioaltare.com/',
  description_en = 'Elio Altare is a wine producer from Italy established in 1948. Nebbiolo is central to the region’s age-worthy Barolo and Barbaresco wines, alongside local varieties such as Barbera and Dolcetto. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '엘리오 알타레(Elio Altare)는 1948년에 시작된 피에몬테의 와인 생산자입니다. Nebbiolo를 중심으로 Barolo와 Barbaresco의 장기 숙성형 와인을 만들며, Barbera와 Dolcetto 등 지역 품종도 함께 다룹니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 412;

-- id=413 | Colgin Cellars
