SET
  founded_year = 1992,
  name_en = 'Colgin Cellars',
  name_ko = '콜긴 셀러스',
  search_keywords = 'Colgin Cellars, 콜긴 셀러스',
  website = 'https://www.colgincellars.com/',
  description_en = 'Colgin Cellars is a wine producer from the United States established in 1992. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '콜긴 셀러스(Colgin Cellars)는 1992년에 시작된 나파 밸리의 와인 생산자입니다. Cabernet Sauvignon을 중심으로 Chardonnay, Merlot, Sauvignon Blanc 등도 생산하며, 따뜻한 낮과 서늘한 밤의 일교차를 이용해 풍부한 과실과 균형 잡힌 산도를 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 413;

