  website = 'https://clonakilla.com.au/',
  description_en = 'Clonakilla is a wine producer from Australia established in 1971. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '클로날킬라(Clonakilla)는 1971년에 시작된 캔버라의 와인 생산자입니다. 지역의 기후와 오래된 포도나무를 활용해 풍부한 과실을 만들면서도 산도와 토양의 개성을 유지하는 스타일을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 422;

