  website = 'https://www.grosset.com.au/',
  description_en = 'Grosset is a wine producer from Australia established in 1981. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '그로세트(Grosset)는 1981년에 시작된 사우스오스트레일리아 (클레어 밸리)의 와인 생산자입니다. 지역의 기후와 오래된 포도나무를 활용해 풍부한 과실을 만들면서도 산도와 토양의 개성을 유지하는 스타일을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
