-- id=424 | Kir-Yianni
UPDATE producer
SET
  founded_year = 1997,
  name_en = 'Kir-Yianni',
  name_ko = '키르 야니',
  search_keywords = 'Kir-Yianni, 키르 야니',
  website = 'https://kiryianni.gr/',
  description_en = 'Kir-Yianni is a wine producer from Greece established in 1997. Native Greek varieties and distinctive island or mountain terroirs are used to preserve acidity, herbs and mineral character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '키르 야니(Kir-Yianni)는 1997년에 시작된 나우사의 와인 생산자입니다. 그리스 토착 품종과 독특한 섬·산악 테루아를 중심으로 높은 산도와 허브·미네랄 풍미를 살리는 스타일을 추구합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 424;

-- id=425 | Domäne Wachau
UPDATE producer
SET
  founded_year = 1938,
  name_en = 'Domäne Wachau',
  name_ko = '도멘 바하우',
  search_keywords = 'Domäne Wachau, Domane Wachau, 도멘 바하우',
  website = 'https://www.domaene-wachau.at/',
  description_en = 'Domäne Wachau is a wine producer from Austria established in 1938. Grüner Veltliner and Riesling from steep Danube terraces combine ripe fruit with acidity, herbal detail and stony minerality. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '도멘 바하우(Domäne Wachau)는 1938년에 시작된 바하우의 와인 생산자입니다. Grüner Veltliner와 Riesling이 중심이며, 도나우 강변의 가파른 계단식 포도밭에서 높은 산도와 잘 익은 과실, 돌·허브 계열의 미네랄을 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 425;

