  description_ko = '폴 자불레 애네(Paul Jaboulet Aîné)는 공식·역사 자료에서 1834년까지 이어지는 뿌리를 확인할 수 있는 론의 와인 생산자입니다. Syrah, Grenache, Mourvèdre, Viognier 등 론의 대표 품종을 활용하며, 북부와 남부의 서로 다른 기후와 토양을 각 생산자의 방식으로 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
