  website = 'https://www.domperignon.com/',
  description_en = 'Dom Pérignon is the vintage-only prestige Champagne of Moët & Chandon rather than an independent physical winery; its modern commercial identity dates from the 1930s. Chardonnay, Pinot Noir and Meunier are blended before traditional-method secondary fermentation and extended lees ageing build texture and complexity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '동 페리뇽(Dom Pérignon)은 모엣 샹동(Moët & Chandon)이 만드는 빈티지 전용 프레스티지 샴페인 브랜드로, 첫 상업 출시가 이루어진 1930년대부터 독자적인 정체성을 구축해 왔습니다. Chardonnay와 Pinot Noir를 바탕으로 오직 빈티지가 선언된 해에만 생산하며, 긴 병 숙성과 Plénitude 개념을 통해 한 빈티지가 시간에 따라 변화하는 모습을 표현하는 데 집중합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
