  description_ko = '뵈브 클리코(Veuve Clicquot)는 공식·역사 자료에서 1772년까지 이어지는 뿌리를 확인할 수 있는 샴페인의 와인 생산자입니다. Chardonnay, Pinot Noir, Meunier를 기반으로 기본 와인과 리저브 와인을 조합하고 병내 2차 발효와 긴 효모 숙성을 통해 섬세한 기포와 복합성을 만듭니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 273;

