  description_en = 'Pio Cesare is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1881. Nebbiolo is central to the region’s age-worthy Barolo and Barbaresco wines, alongside local varieties such as Barbera and Dolcetto. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '피오 체사레(Pio Cesare)는 공식·역사 자료에서 1881년까지 이어지는 뿌리를 확인할 수 있는 피에몬테의 와인 생산자입니다. Nebbiolo를 중심으로 Barolo와 Barbaresco의 장기 숙성형 와인을 만들며, Barbera와 Dolcetto 등 지역 품종도 함께 다룹니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 285;

