  website = 'https://allegrini.it/',
  description_en = 'Allegrini is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1854. The region spans Valpolicella and Amarone based on Corvina as well as white wines, with appassimento and extended ageing playing important roles. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '알레그리니(Allegrini)는 공식·역사 자료에서 1854년까지 이어지는 뿌리를 확인할 수 있는 베네토의 와인 생산자입니다. Corvina 계열의 Valpolicella·Amarone부터 지역 화이트 와인까지 다양한 스타일을 다루며, 건조 포도와 장기 숙성 같은 전통 기법이 중요한 역할을 합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
