  website = 'https://planeta.it/',
  description_en = 'Planeta is a wine producer from Italy established in 1995. Native grapes such as Nero d’Avola, Nerello Mascalese and Carricante reflect both Mediterranean warmth and Sicily’s diverse volcanic and limestone soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '플라네타(Planeta)는 1995년에 시작된 시칠리아의 와인 생산자입니다. Nero d’Avola, Nerello Mascalese, Carricante 등 토착 품종을 중심으로 지중해의 따뜻함과 화산·석회질 토양의 개성을 함께 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
