  description_en = 'Mastroberardino is a wine producer from Italy whose documented estate, family or commercial history reaches back to 1878. Local varieties are central, with traditional methods and modern precision combined to express regional terroir. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
