  description_ko = '마르케스 데 리스칼(Marqués de Riscal)은 공식·역사 자료에서 1858년까지 이어지는 뿌리를 확인할 수 있는 리오하의 와인 생산자입니다. Tempranillo를 중심으로 Garnacha와 Graciano 등을 블렌딩하며, 오크 숙성과 병 숙성을 통해 향신료·가죽·붉은 과실이 어우러지는 스타일을 발전시켜 왔습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
