  description_ko = '클로스 모가도르(Clos Mogador)는 1979년에 시작된 프리오라트의 와인 생산자입니다. Garnacha와 Cariñena를 중심으로 리코렐라 점판암 토양과 가파른 경사지의 낮은 수확량을 통해 강한 농축감과 미네랄을 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 308;

