  description_ko = '곤살레스 비아스 (티오 페페)(González Byass (Tío Pepe))는 공식·역사 자료에서 1835년까지 이어지는 뿌리를 확인할 수 있는 헤레스 (셰리)의 와인 생산자입니다. Jerez의 대형 셰리 하우스로, Palomino 기반의 드라이 Fino Tío Pepe와 솔레라 시스템을 통해 산뜻한 플로르 숙성 스타일을 세계적으로 알렸습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 309;

