  description_ko = '블랜디스(Blandy''s)는 공식·역사 자료에서 1811년까지 이어지는 뿌리를 확인할 수 있는 마데이라의 와인 생산자입니다. 포르투갈 토착 품종을 중심으로 지역의 전통적인 블렌딩 문화와 현대적인 포도밭 관리를 결합합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 319;

-- id=320 | Sogrape
UPDATE producer
SET
  founded_year = 1942,
  name_en = 'Sogrape',
  name_ko = '소그라페 (마테우스)',
  search_keywords = 'Sogrape, 소그라페 (마테우스), 소그라페',
  website = 'https://sogrape.com/',
  description_en = 'Sogrape is a Portuguese family wine group founded in 1942, operating multiple estates and brands rather than a single winery. Native varieties such as Touriga Nacional and Touriga Franca grow on steep schist slopes and are used for both Port and structured dry wines. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '소그라페(Sogrape)는 1942년에 설립된 포르투갈의 가족 와인 그룹으로, 한 개의 와이너리보다 여러 산지와 브랜드를 운영하는 종합 생산자입니다. Fernando van Zeller Guedes가 시작한 뒤 Mateus를 세계적으로 성장시켰고, 오늘날에는 Casa Ferreirinha, Sandeman 등 포르투갈 안팎의 여러 에스테이트와 브랜드를 운영합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 320;

-- id=321 | Egon Müller (Scharzhof)
UPDATE producer
SET
  founded_year = 1797,
  name_en = 'Egon Müller (Scharzhof)',
  name_ko = '에곤 뮐러',
  search_keywords = 'Egon Müller (Scharzhof), Egon Muller (Scharzhof), 에곤 뮐러, Egon Müller',
  website = 'https://www.scharzhof.de/',
  description_en = 'Egon Müller (Scharzhof) is a wine producer from Germany whose documented estate, family or commercial history reaches back to 1797. Riesling dominates, with steep slate slopes and a cool climate producing high acidity, moderate alcohol and precise fruit and mineral character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '에곤 뮐러(Egon Müller (Scharzhof))는 공식·역사 자료에서 1797년까지 이어지는 뿌리를 확인할 수 있는 모젤의 와인 생산자입니다. Mosel Saar의 Scharzhofberger 포도밭을 중심으로 Riesling Kabinett부터 Trockenbeerenauslese까지 극도로 섬세하고 장수하는 와인을 만드는 대표 생산자입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 321;

