  website = 'https://drloosen.com/',
  description_en = 'Dr. Loosen is a wine producer from Germany established in 1988. Riesling dominates, with steep slate slopes and a cool climate producing high acidity, moderate alcohol and precise fruit and mineral character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '닥터 로젠(Dr. Loosen)은 1988년에 시작된 모젤의 와인 생산자입니다. Ernst Loosen이 1988년 가족 에스테이트 운영을 맡은 뒤 Mosel의 오래된 Riesling 포도밭과 전통적인 Prädikat 스타일을 세계적으로 알리는 데 큰 역할을 했습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
