  website = 'https://www.opusonewinery.com/',
  description_en = 'Opus One is a wine producer from the United States established in 1979. Created in 1979 by Robert Mondavi and Baron Philippe de Rothschild, it focuses on a single Oakville Cabernet-led Bordeaux blend. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
