  search_keywords = 'Stag''s Leap Wine Cellars, 스택스 립 와인 셀러스',
  website = 'https://www.stagsleapwinecellars.com/',
  description_en = 'Stag''s Leap Wine Cellars is a wine producer from the United States established in 1970. Its 1973 S.L.V. Cabernet Sauvignon won the red-wine category at the 1976 Judgment of Paris; Marchesi Antinori has been the sole owner since 2023. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '스택스 립 와인 셀러스(Stag''s Leap Wine Cellars)는 1970년에 시작된 나파 밸리의 와인 생산자입니다. 1973 S.L.V. Cabernet Sauvignon이 1976년 파리의 심판 레드 부문에서 1위를 차지하며 나파 와인의 국제적 위상을 바꿨습니다. 2023년부터 Marchesi Antinori가 단독 소유합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 331;

-- id=332 | Ridge Vineyards
UPDATE producer
SET
  founded_year = 1962,
  name_en = 'Ridge Vineyards',
  name_ko = '리지 빈야드',
  search_keywords = 'Ridge Vineyards, 리지 빈야드',
  website = 'https://www.ridgewine.com/',
  description_en = 'Ridge Vineyards is a wine producer from the United States established in 1962. Varieties are matched to local climate and vineyard conditions, with an emphasis on balancing ripe fruit, acidity and oak. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '리지 빈야드(Ridge Vineyards)는 1962년에 시작된 캘리포니아의 와인 생산자입니다. Monte Bello의 석회질 산지에서 Cabernet Sauvignon을, Lytton Springs 등에서는 오래된 Zinfandel 혼식 포도밭을 다루며, 최소 개입과 투명한 라벨 정보로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 332;

