  description_en = 'Caymus Vineyards is a wine producer from the United States established in 1972. Cabernet Sauvignon is central, alongside Chardonnay, Merlot and Sauvignon Blanc, with warm days and cool nights supporting ripe fruit and balanced acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
