  description_ko = '도멘 드루앵 오리건(Domaine Drouhin Oregon)은 1987년에 시작된 오리건의 와인 생산자입니다. Willamette Valley를 중심으로 Pinot Noir와 Chardonnay가 핵심이며, 서늘한 기후가 만드는 선명한 산도와 향기, 토양별 세밀한 차이를 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 342;

