  search_keywords = 'The Eyrie Vineyards, 아이리 빈야드',
  website = 'https://eyrievineyards.com/',
  description_en = 'The Eyrie Vineyards is a wine producer from the United States established in 1965. Pinot Noir and Chardonnay are central, particularly in the Willamette Valley, where a cool climate supports aromatic detail, acidity and site expression. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '아이리 빈야드(The Eyrie Vineyards)는 1965년에 시작된 오리건의 와인 생산자입니다. David Lett가 1965년 Willamette Valley에 Pinot Noir와 Chardonnay를 심으며 오리건 고급 와인의 역사를 연 선구자 가운데 하나입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
