  search_keywords = 'Quilceda Creek, 퀼세다 크릭',
  website = 'https://quilcedacreek.com/',
  description_en = 'Quilceda Creek is a wine producer from the United States established in 1979. Cabernet Sauvignon, Merlot, Syrah and Riesling thrive in the dry continental climate, often combining ripe fruit with fresh acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '퀼세다 크릭(Quilceda Creek)은 1979년에 시작된 워싱턴의 와인 생산자입니다. Cabernet Sauvignon, Merlot, Syrah, Riesling 등 다양한 품종을 건조한 대륙성 기후에서 재배하며, 잘 익은 과실과 선명한 산도를 동시에 얻는 것이 특징입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
