  website = 'https://www.ste-michelle.com/',
  description_en = 'Chateau Ste. Michelle is a wine producer from the United States established in 1934. Cabernet Sauvignon, Merlot, Syrah and Riesling thrive in the dry continental climate, often combining ripe fruit with fresh acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '샤토 생 미셸(Chateau Ste. Michelle)은 1934년에 시작된 워싱턴의 와인 생산자입니다. 워싱턴주 와인 산업의 대형 기반을 구축한 대표 생산자로, Riesling과 Cabernet Sauvignon 등 폭넓은 품종을 다루며 장기 재배농가 네트워크를 운영합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
