  description_ko = '카테나 사파타(Catena Zapata)는 1902년에 시작된 멘도사의 와인 생산자입니다. Nicolás Catena가 Mendoza의 고지대 포도밭 가능성을 체계적으로 연구하며 Malbec의 국제적 위상을 끌어올렸고, Adrianna Vineyard 같은 고산 단일 포도밭 프로젝트로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
