  description_en = 'Concha y Toro is a wine producer from Chile whose documented estate, family or commercial history reaches back to 1883. Cabernet Sauvignon is central to classic Chilean Bordeaux-style wines, with Andean gravel soils and diurnal shifts providing structure and freshness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
