  description_ko = '몬테스(Montes)는 1988년에 시작된 콜차과의 와인 생산자입니다. 안데스와 태평양의 영향을 받는 포도밭에서 익은 과실과 신선한 산도를 함께 살리는 것을 중요하게 봅니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 354;

-- id=355 | Viña Santa Rita
UPDATE producer
SET
  founded_year = 1880,
  name_en = 'Viña Santa Rita',
  name_ko = '비냐 산타 리타',
  search_keywords = 'Viña Santa Rita, Vina Santa Rita, 비냐 산타 리타',
  website = 'https://www.santarita.com/',
  description_en = 'Viña Santa Rita is a wine producer from Chile whose documented estate, family or commercial history reaches back to 1880. Cabernet Sauvignon is central to classic Chilean Bordeaux-style wines, with Andean gravel soils and diurnal shifts providing structure and freshness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '비냐 산타 리타(Viña Santa Rita)는 공식·역사 자료에서 1880년까지 이어지는 뿌리를 확인할 수 있는 마이포의 와인 생산자입니다. Cabernet Sauvignon을 중심으로 칠레의 고전적인 보르도 품종 스타일을 발전시켰으며, 안데스 산기슭의 자갈 토양과 큰 일교차가 구조와 신선함을 더합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 355;

-- id=356 | Seña
UPDATE producer
SET
  founded_year = 1995,
  name_en = 'Seña',
  name_ko = '비냐 세냐',
  search_keywords = 'Seña, Sena, 비냐 세냐',
  website = 'https://www.sena.cl/',
  description_en = 'Seña is a wine producer from Chile established in 1995. Vineyards influenced by the Andes and Pacific combine ripe fruit with freshness and acidity. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '비냐 세냐(Seña)는 1995년에 시작된 아콩카과의 와인 생산자입니다. Eduardo Chadwick과 Robert Mondavi가 1995년 시작한 칠레의 선구적 국제 합작 와인으로, Aconcagua의 바이오다이내믹 에스테이트에서 Cabernet Sauvignon 중심 블렌드를 생산합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 356;

-- id=357 | Penfolds
UPDATE producer
SET
  founded_year = 1844,
  name_en = 'Penfolds',
  name_ko = '펜폴즈',
  search_keywords = 'Penfolds, 펜폴즈',
  website = 'https://www.penfolds.com/',
  description_en = 'Penfolds is a wine producer from Australia whose documented estate, family or commercial history reaches back to 1844. The wines use local climate and, in many cases, old vines to combine ripe fruit with acidity and site character. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '펜폴즈(Penfolds)는 공식·역사 자료에서 1844년까지 이어지는 뿌리를 확인할 수 있는 사우스오스트레일리아의 와인 생산자입니다. 1844년부터 이어진 호주의 대표 생산자로, 여러 지역과 포도밭의 원액을 블렌딩해 일관된 스타일을 만드는 철학을 발전시켰으며 Grange가 그 정점에 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 357;

