  description_ko = '헨쉬케(Henschke)는 공식·역사 자료에서 1868년까지 이어지는 뿌리를 확인할 수 있는 사우스오스트레일리아의 와인 생산자입니다. Eden Valley의 Hill of Grace를 비롯한 오래된 Shiraz 포도밭을 가족이 보존하고 있으며, 단일 포도밭과 오래된 포도나무의 개성을 세밀하게 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
