  description_en = 'Cloudy Bay is a wine producer from New Zealand established in 1985. Founded in 1985, it was pivotal in establishing Marlborough Sauvignon Blanc internationally and is now part of LVMH. Sauvignon Blanc leads the region with vivid citrus, tropical fruit, herbs and acidity, alongside growing Pinot Noir and Chardonnay production. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '클라우디 베이(Cloudy Bay)는 1985년에 시작된 말버러의 와인 생산자입니다. 1985년 설립 이후 Marlborough Sauvignon Blanc의 선명한 시트러스·허브 스타일을 세계 시장에 알리는 데 결정적인 역할을 했으며 현재 LVMH 소속입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 366;

-- id=367 | Felton Road
