  founded_year = 1991,
  name_en = 'Felton Road',
  name_ko = '펠튼 로드',
  search_keywords = 'Felton Road, 펠튼 로드',
  website = 'https://feltonroad.com/',
  description_en = 'Felton Road is a wine producer from New Zealand established in 1991. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '펠튼 로드(Felton Road)는 1991년에 시작된 센트럴오타고의 와인 생산자입니다. Central Otago Bannockburn의 단일 포도밭 Pinot Noir와 Chardonnay를 바이오다이내믹 방식으로 재배하며, 자연 발효와 절제된 오크 사용을 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
