  website = 'https://www.villamariawines.com/',
  description_en = 'Villa Maria is a wine producer from New Zealand established in 1961. Sauvignon Blanc leads the region with vivid citrus, tropical fruit, herbs and acidity, alongside growing Pinot Noir and Chardonnay production. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '빌라 마리아(Villa Maria)는 1961년에 시작된 말버러 / 호크스 베이의 와인 생산자입니다. Sauvignon Blanc을 중심으로 강한 향과 높은 산도, 시트러스·열대과일·허브의 선명한 풍미를 보여주며 Pinot Noir와 Chardonnay도 생산합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
