  description_en = 'Te Mata Estate is a wine producer from New Zealand whose documented estate, family or commercial history reaches back to 1896. A cool maritime climate supports vivid aromatics and acidity, with increasing focus on vineyard-specific differences. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '테 마타 이스테이트(Te Mata Estate)는 공식·역사 자료에서 1896년까지 이어지는 뿌리를 확인할 수 있는 혹스베이의 와인 생산자입니다. 서늘한 해양성 기후를 활용해 선명한 향과 높은 산도를 살리고, 지역별 포도밭 차이를 세밀하게 표현합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
