  description_en = 'Suntory Tomi no Oka is a wine producer from Japan established in 1909. Koshu, Muscat Bailey A and international varieties are adapted to Japan’s humid climate, with emphasis on delicacy and freshness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '산토리 토미노오카(Suntory Tomi no Oka)는 1909년에 시작된 야마나시의 와인 생산자입니다. Koshu, Muscat Bailey A와 국제 품종을 일본의 습윤한 기후에 맞춰 재배하며, 섬세한 향과 산도를 살리는 양조를 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 377;

-- id=378 | Coco Farm & Winery
UPDATE producer
SET
  founded_year = 1958,
  name_en = 'Coco Farm & Winery',
  name_ko = '코코 팜 와이너리',
  search_keywords = 'Coco Farm & Winery, 코코 팜 와이너리',
  website = 'https://cocowine.com/',
  description_en = 'Coco Farm & Winery is a wine producer from Japan established in 1958. Koshu, Muscat Bailey A and international varieties are adapted to Japan’s humid climate, with emphasis on delicacy and freshness. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '코코 팜 와이너리(Coco Farm & Winery)는 1958년에 시작된 도치기 (아시카가)의 와인 생산자입니다. Koshu, Muscat Bailey A와 국제 품종을 일본의 습윤한 기후에 맞춰 재배하며, 섬세한 향과 산도를 살리는 양조를 중시합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
WHERE id = 378;

-- id=379 | Ao Yun
UPDATE producer
SET
  founded_year = 2013,
  name_en = 'Ao Yun',
  name_ko = '아오윈',
  search_keywords = 'Ao Yun, 아오윈',
  website = 'https://www.aoyun-wine.com/',
  description_en = 'Ao Yun is a wine producer from China established in 2013. High elevations, dryness and large diurnal shifts are used to develop distinctive regional expressions of Cabernet and other international varieties. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '아오윈(Ao Yun)은 2013년에 시작된 윈난의 와인 생산자입니다. LVMH가 중국 윈난성 샹그릴라 고지대에 조성한 프로젝트로, 해발 2,000m가 넘는 포도밭의 Cabernet Sauvignon 중심 블렌드를 수작업 중심으로 생산합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 379;

-- id=380 | Changyu
UPDATE producer
SET
  founded_year = 1892,
  name_en = 'Changyu',
  name_ko = '장위',
  search_keywords = 'Changyu, 장위',
  website = 'https://www.changyu.com.cn/',
  description_en = 'Changyu is a wine producer from China whose documented estate, family or commercial history reaches back to 1892. High elevations, dryness and large diurnal shifts are used to develop distinctive regional expressions of Cabernet and other international varieties. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '장위(Changyu)는 공식·역사 자료에서 1892년까지 이어지는 뿌리를 확인할 수 있는 산둥 (옌타이)의 와인 생산자입니다. 고도와 건조도, 일교차가 큰 포도산지를 활용해 Cabernet 계열을 비롯한 국제 품종의 지역적 표현을 발전시키고 있습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 380;

