  website = 'https://www.silverheights.cn/',
  description_en = 'Silver Heights is a wine producer from China established in 2007. High elevations, dryness and large diurnal shifts are used to develop distinctive regional expressions of Cabernet and other international varieties. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
