  website = 'https://sulavineyards.com/',
  description_en = 'Sula Vineyards is a wine producer from India established in 1999. Careful harvest timing and elevation management help preserve freshness in warm-climate varieties such as Chenin Blanc and Shiraz. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '술라 빈야드(Sula Vineyards)는 1999년에 시작된 나시크 (마하라슈트라)의 와인 생산자입니다. 따뜻한 기후에서 수확 시기와 포도밭 고도를 세밀하게 관리하며 Chenin Blanc, Shiraz 등 다양한 품종의 신선함을 유지합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
