  description_en = 'Grover Zampa Vineyards is a wine producer from India established in 1988. Careful harvest timing and elevation management help preserve freshness in warm-climate varieties such as Chenin Blanc and Shiraz. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
