  search_keywords = 'Nyetimber, 나이팀버',
  website = 'https://nyetimber.com/',
  description_en = 'Nyetimber is a wine producer from England / United Kingdom established in 1988. Chardonnay and Pinot Noir underpin traditional-method sparkling wines, with the cool climate and chalky soils preserving high acidity and finesse. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '나이팀버(Nyetimber)는 1988년에 시작된 잉글랜드의 와인 생산자입니다. West Sussex와 Hampshire 등의 석회질 토양에서 전통 방식으로 Chardonnay·Pinot Noir·Meunier 스파클링 와인을 생산하며 영국 프리미엄 스파클링의 선구자로 평가됩니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
