  website = 'https://www.chapeldown.com/',
  description_en = 'Chapel Down is a wine producer from England / United Kingdom established in 2001. Chardonnay and Pinot Noir underpin traditional-method sparkling wines, with the cool climate and chalky soils preserving high acidity and finesse. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
