  website = '',
  description_en = 'Yeopo Wine Farm is a wine producer from South Korea established in 2005. The producer works with grapes and fruit adapted to Korean conditions, linking small-scale winemaking with local agriculture and tourism. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '여포와인농장(Yeopo Wine Farm)은 2005년에 시작된 충청도의 와인 생산자입니다. 국내 기후에 적응한 포도 품종과 과실을 활용하며, 지역 농업과 관광을 연결하는 소규모 와인 생산을 발전시켜 왔습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 389;

