  website = '',
  description_en = 'Sanmeoru Farm is a wine producer from South Korea established in 1996. The producer works with grapes and fruit adapted to Korean conditions, linking small-scale winemaking with local agriculture and tourism. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '산머루 농원(Sanmeoru Farm)은 1996년에 시작된 경기도의 와인 생산자입니다. 국내 기후에 적응한 포도 품종과 과실을 활용하며, 지역 농업과 관광을 연결하는 소규모 와인 생산을 발전시켜 왔습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
