  founded_year = 1930,
  name_en = 'Château Musar',
  name_ko = '샤토 무사',
  search_keywords = 'Château Musar, Chateau Musar, 샤토 무사',
  website = 'https://chateaumusar.com/',
  description_en = 'Château Musar is a wine producer from Lebanon established in 1930. High elevations and a dry climate support Mediterranean and international varieties that gain complexity through ageing. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '샤토 무사(Château Musar)는 1930년에 시작된 베카 밸리의 와인 생산자입니다. Gaston Hochar가 1930년 레바논 Bekaa Valley에 설립했으며, 내전기에도 생산을 이어간 역사와 장기 숙성·빈티지 편차를 숨기지 않는 독특한 레드 블렌드로 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 392;

