  search_keywords = 'The Royal Tokaji, 로열 토카지',
  website = 'https://royal-tokaji.com/',
  description_en = 'The Royal Tokaji is a wine producer from Hungary established in 1990. Furmint and Hárslevelű support both dry wines and botrytized Tokaji Aszú, shaped by volcanic soils and historic underground cellars. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '로열 토카지(The Royal Tokaji)는 1990년에 시작된 토카이의 와인 생산자입니다. Furmint와 Hárslevelű를 중심으로 드라이 와인과 귀부 포도로 만드는 Tokaji Aszú를 생산하며, 화산성 토양과 오래된 지하 셀러가 중요한 역할을 합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
