  search_keywords = 'Inniskillin, 이니스킬린',
  website = 'https://www.inniskillin.com/',
  description_en = 'Inniskillin is a wine producer from Canada established in 1975. Cold winters and strong seasonal contrasts support fresh table wines and naturally frozen-grape Icewine. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
