  website = 'https://sigalas-wine.com/',
  description_en = 'Domaine Sigalas is a wine producer from Greece established in 1991. Assyrtiko grown in volcanic ash and pumice, often in low basket-trained vines, produces intense acidity and a saline mineral profile. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
