  website = 'https://schuchmann-wines.com/',
  description_en = 'Schuchmann Wines is a wine producer from Georgia established in 2008. Native Georgian grapes such as Saperavi and Rkatsiteli are made with both traditional qvevri methods and modern cellar techniques. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '슈흐만 와인스(Schuchmann Wines)는 2008년에 시작된 카헤티의 와인 생산자입니다. Saperavi와 Rkatsiteli 등 조지아 토착 품종을 사용하며, 전통적인 qvevri 발효와 현대식 양조를 병행해 다양한 스타일을 만듭니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
