  website = 'https://www.lafite.com/domaines/chateau-lafite-rothschild/',
  description_en = 'Château Lafite Rothschild is a wine producer from France whose documented estate, family or commercial history reaches back to 1868. Cabernet Sauvignon and Merlot are central to the region, with blending used to express the balance between site, soil and vintage. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Across the range, the producer’s character comes from the link between site, harvest decisions, fermentation and ageing.',
  description_ko = '샤토 라피트 로칠드(Château Lafite Rothschild)는 공식·역사 자료에서 1868년까지 이어지는 뿌리를 확인할 수 있는 보르도의 와인 생산자입니다. Pauillac의 1855년 1등급 샤토로, Cabernet Sauvignon 중심의 우아하고 정교한 구조와 매우 긴 숙성 잠재력으로 보르도 최고급 와인의 기준 가운데 하나입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
