  description_en = 'Château Mouton Rothschild is a wine producer from France whose documented estate, family or commercial history reaches back to 1853. Cabernet Sauvignon and Merlot are central to the region, with blending used to express the balance between site, soil and vintage. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '샤토 무통 로칠드(Château Mouton Rothschild)는 공식·역사 자료에서 1853년까지 이어지는 뿌리를 확인할 수 있는 보르도의 와인 생산자입니다. Pauillac 1등급 샤토로, 1973년 2등급에서 1등급으로 승격된 유일한 사례이며 매 빈티지 세계적인 예술가가 디자인한 라벨을 사용하는 전통으로도 유명합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 229;

