  description_en = 'Domaine Leflaive is a wine producer from France whose documented estate, family or commercial history reaches back to 1717. Pinot Noir and Chardonnay dominate, with a strong focus on expressing the differences between individual vineyard parcels and soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The flagship wines are best understood in the context of the vineyards, varieties and maturation choices behind them.',
  description_ko = '도멘 르플레브(Domaine Leflaive)는 공식·역사 자료에서 1717년까지 이어지는 뿌리를 확인할 수 있는 부르고뉴의 와인 생산자입니다. Puligny-Montrachet의 대표 Chardonnay 도멘으로, Chevalier-Montrachet 등 최고급 포도밭을 보유하고 1990년대부터 바이오다이내믹 재배를 선도해 왔습니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 품종과 핵심 포도밭, 오크 및 병 숙성의 사용 방식을 함께 살펴보면 이 생산자가 추구하는 와인의 방향을 더욱 분명하게 이해할 수 있습니다.',
  type = 'WINERY'
WHERE id = 251;

