  search_keywords = 'Domaine Coche-Dury, 도멘 코슈 뒤리, Coche-Dury',
  website = '',
  description_en = 'Domaine Coche-Dury is a wine producer from France established in 1940. Pinot Noir and Chardonnay dominate, with a strong focus on expressing the differences between individual vineyard parcels and soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. The identity of the producer becomes clearest in the way vineyard origin, grape variety and ageing choices interact in the finished wines.',
  description_ko = '도멘 코슈 뒤리(Domaine Coche-Dury)는 1940년에 시작된 부르고뉴의 와인 생산자입니다. Pinot Noir와 Chardonnay가 중심이며, 포도밭의 작은 구획과 토양 차이를 세밀하게 반영하는 것이 생산 철학의 핵심입니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 대표 와인들은 포도 품종의 성격뿐 아니라 포도밭의 위치와 숙성 방식에 따라 뚜렷한 차이를 보여주며, 이러한 선택이 생산자의 스타일을 이해하는 핵심입니다.',
  type = 'WINERY'
WHERE id = 252;

