  search_keywords = 'Domaine Dujac, 도멘 뒤자크, Dujac',
  website = 'https://www.dujac.com/',
  description_en = 'Domaine Dujac is a wine producer from France established in 1967. Pinot Noir and Chardonnay dominate, with a strong focus on expressing the differences between individual vineyard parcels and soils. Vineyard work, harvest timing, fermentation and maturation are managed with the aim of preserving fruit quality and making vintage and site differences clear. Rather than relying on reputation alone, its house style is defined by consistent decisions in the vineyard, cellar and maturation process.',
  description_ko = '도멘 뒤자크(Domaine Dujac)는 1967년에 시작된 부르고뉴의 와인 생산자입니다. Morey-Saint-Denis를 기반으로 줄기 사용과 섬세한 추출을 활용해 향기롭고 구조감 있는 Pinot Noir를 만들며, 여러 Côte de Nuits Grand Cru를 보유합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 지역의 전통을 그대로 반복하기보다 포도밭과 빈티지의 조건을 세밀하게 읽어 균형과 개성을 만들어 간다는 점이 이 생산자의 중요한 특징입니다.',
  type = 'WINERY'
WHERE id = 253;

