  description_ko = '메종 루이 자도(Maison Louis Jadot)는 공식·역사 자료에서 1859년까지 이어지는 뿌리를 확인할 수 있는 부르고뉴의 와인 생산자입니다. 부르고뉴 전역에서 도멘 소유 포도밭과 장기 계약 포도를 함께 다루는 대형 메종으로, 지역급부터 Grand Cru까지 폭넓은 라인업을 통해 각 아펠라시옹의 전형성을 강조합니다. 포도 재배와 수확 시점, 발효와 숙성 방식을 세밀하게 조절해 원료의 품질과 빈티지의 차이를 가능한 한 선명하게 보여주는 것을 중요하게 생각합니다. 생산 규모와 관계없이 원료의 출처, 수확 시점, 발효와 숙성에 대한 선택이 하나의 일관된 스타일로 이어진다는 점에서 생산자 고유의 정체성이 드러납니다.',
  type = 'WINERY'
